13	// Helper to encode JSON to Hex to prevent USB scanner keyboard layout issues (US vs ABNT2)
14	const encodeHex = (str: string) => {
15	    return Array.from(new TextEncoder().encode(str))
16	        .map(b => b.toString(16).padStart(2, '0'))
17	        .join('');
18	};
