108	
109	    // Vendor Info (Mock for now, future dynamic)
110	    const [vendor, setVendor] = useState("MOMMA");
111	
112	    // Selection States
113	    const [product, setProduct] = useState<Product>(EMPTY_PRODUCT);
114	    const [selectedStorage, setSelectedStorage] = useState<string>("Temperatura Ambiente");
