294	
295	    const handlePrint = async () => {
296	        const parsedQuantity = typeof printQuantity === 'string' ? parseInt(printQuantity) : printQuantity;
297	        const numLabels = isNaN(parsedQuantity as number) || (parsedQuantity as number) <= 0 ? 0 : parsedQuantity as number;
298	
299	        if (numLabels <= 0) {
