301	            return;
302	        }
303	
304	        // Generate unique IDs for each label to print
305	        // Use a fallback for non-secure contexts (like HTTP on local network) where crypto.randomUUID is not available
306	        const newUids = Array.from({ length: numLabels }).map(() => {
307	            if (typeof crypto !== 'undefined' && crypto.randomUUID) {
308	                return crypto.randomUUID().split('-')[0];
309	            }
310	            // Fallback for HTTP connections (e.g. accessing via local IP)
311	            return Math.random().toString(36).substring(2, 10);
312	        });
313	
314	        // Persistir cada UID em etiquetas_qr ANTES de imprimir (rastreabilidade fim-a-fim).
