449	                                                e.stopPropagation();
450	                                            }}
451	                                        />
452	                                    </div>
453	                                )}
454	                            </div>
455	
456	                            {/* Product Form - Only show if printing product label */}
457	                            {labelType === "produto" && (
458	                                <div className="space-y-6 animate-in fade-in duration-300">
459	                                    {/* Product Search */}
460	                                    <div className="space-y-4">
461	                                        <Label htmlFor="product-search" className="text-xs uppercase font-bold text-muted-foreground tracking-wider">Produto</Label>
462	                                        <Popover open={open} onOpenChange={setOpen}>
463	                                            <PopoverTrigger asChild>
464	                                                <Button
465	                                                    data-mia-action="abrir-busca-produto"
466	                                                    variant="outline"
467	                                                    role="combobox"
468	                                                    aria-expanded={open}
469	                                                    className="w-full justify-between h-14 rounded-xl text-base border-2 hover:border-[#57715B]/50"
