import { useState, useRef, useEffect } from "react";
import { createPortal } from "react-dom";
import { ArrowLeft, Printer, Star, Minus, Plus, Search, Leaf, ScanLine } from "lucide-react";
import { useNavigate } from "react-router-dom";
import QRCode from "react-qr-code";
import { Button } from "@/shared/ui/button";
import { Card, CardContent } from "@/shared/ui/card";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { Textarea } from "@/shared/ui/textarea";
import { Badge } from "@/shared/ui/badge";

// Helper to encode JSON to Hex to prevent USB scanner keyboard layout issues (US vs ABNT2)
const encodeHex = (str: string) => {
    return Array.from(new TextEncoder().encode(str))
        .map(b => b.toString(16).padStart(2, '0'))
        .join('');
};

// Calcula font-size ideal para etiqueta de loja (60mm × 40mm, padding 2mm → área útil 56mm × 36mm)
// Respeita quebras de linha manuais (\n): a linha mais longa determina a largura mínima,
// e o total de linhas determina a altura necessária.
const getStoreLabelFontSize = (text: string): string => {
    const upper = (text || '').toUpperCase();
    const lines = upper.split('\n').filter(l => l.trim().length > 0);
    // IMPORTANTE: reduce começa com '' para pegar o máximo por linha, não o texto todo concatenado
    const longestLine = lines.reduce((a, b) => (a.length > b.length ? a : b), '');
    const maxLen = (longestLine.trim().length) || 1;
    const lineCount = Math.max(lines.length, 1);

    // Bold uppercase Arial em 56mm: char_width ≈ pt × 0.353mm × 0.63
    // → chars_per_line = 56 / (pt × 0.353 × 0.63) = 251 / pt
    // lineHeight=1.15: line_height_mm = pt × 0.353 × 1.15
    // → lines_avail = 36 / (pt × 0.353 × 1.15) = 88.6 / pt
    for (let pt = 24; pt >= 7; pt--) {
        const charsPerLine = Math.floor(251 / pt);
        const linesAvail = Math.floor(88.6 / pt);
        if (maxLen <= charsPerLine && lineCount <= linesAvail) return `${pt}pt`;
    }
    return '7pt';
};

import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/shared/ui/select";
import { format } from "date-fns";
import { Separator } from "@/shared/ui/separator";
import { useToast } from "@/shared/ui/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/shared/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/ui/popover";
import { Check, ChevronsUpDown } from "lucide-react";
import { cn } from "@/shared/lib/utils";
import { isLoteRecente } from "@/shared/lib/lote-recency";

import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/shared/ui/dialog";
import { EmbalagemList } from "@/features/produtos/ui/EmbalagemList";
import { BatchList } from "@/components/logistica/BatchList";
import { Settings2, PackagePlus, Layers } from "lucide-react";
import { useStore } from "@/shared/contexts/StoreContext";
import { useAuth } from "@/shared/hooks/useAuth";

// Interface for Product Data
interface Product {
    id: string;
    name: string;
    category: string;
    location: string;
    storage: string;
    validity_days: number;
    image_url?: string;
}

// Interface for Batch Data from lotes table
interface BatchOption {
    id: string;
    codigo: string;
    data_validade: string;
    data_fabricacao: string | null;
    created_at: string | null;
}

// Default empty state
const EMPTY_PRODUCT: Product = {
    id: "",
    name: "Selecione um Produto",
    category: "-",
    location: "-",
    storage: "-",
    validity_days: 0
};

import { Switch } from "@/shared/ui/switch";

export function LabelPrintingContent({ isEmbedded = false }: { isEmbedded?: boolean }) {
    const navigate = useNavigate();
    const { toast } = useToast();
    const { selectedStore } = useStore();
    const { userProfile } = useAuth();
    const [searchTerm, setSearchTerm] = useState("");
    const [products, setProducts] = useState<Product[]>([]);
    const [open, setOpen] = useState(false);
    const [loading, setLoading] = useState(false);

    // Vendor Info (Mock for now, future dynamic)
    const [vendor, setVendor] = useState("MOMMA");

    // Selection States
    const [product, setProduct] = useState<Product>(EMPTY_PRODUCT);
    const [selectedStorage, setSelectedStorage] = useState<string>("Temperatura Ambiente");
    const [responsibleName, setResponsibleName] = useState<string>("");
    const [batches, setBatches] = useState<BatchOption[]>([]);
    const [selectedBatch, setSelectedBatch] = useState<BatchOption | null>(null);
    // Lotes antigos ficam ocultos por padrão para não serem impressos por engano.
    const [showOldBatches, setShowOldBatches] = useState(false);
    const [embalagens, setEmbalagens] = useState<any[]>([]);
    const [selectedEmbalagem, setSelectedEmbalagem] = useState<any>(null);
    const [showEmbalagemManager, setShowEmbalagemManager] = useState(false);
    // ── Nova modelagem da etiqueta: 3 eixos independentes ──────────────────
    // tipoEmbalagem = container fisico (caixa/saco/balde/pote/galao/lata/pacote/garrafa/tambor/granel)
    // unidadeInterna = unidade do conteudo (un/kg/g/l/ml/sache)
    // quantidadeInterna = quantos do conteudo cabem na embalagem
    const [tipoEmbalagem, setTipoEmbalagem] = useState<string>("caixa");
    const [unidadeInterna, setUnidadeInterna] = useState<string>("un");
    const [quantidadeInterna, setQuantidadeInterna] = useState<number>(1);
    const [showLotManager, setShowLotManager] = useState(false);
    const [labelType, setLabelType] = useState<"produto" | "loja" | "aberto">("produto");
    const [storeLabelText, setStoreLabelText] = useState("");
    const [printQuantity, setPrintQuantity] = useState<number | string>(1);
    const [printUids, setPrintUids] = useState<string[]>([]);
    const [isPrinting, setIsPrinting] = useState(false);

    // Initialize responsible name from logged user
    useEffect(() => {
        if (userProfile?.nome && !responsibleName) {
            setResponsibleName(userProfile.nome.split(' ')[0]);
        }
    }, [userProfile, responsibleName]);

    // Initialize store label text from selected store
    useEffect(() => {
        if (selectedStore) {
            setStoreLabelText(selectedStore.shortName || selectedStore.name);
        }
    }, [selectedStore]);

    // Helper to refresh packages — agora inclui tipo_embalagem + unidade_interna
    const refreshEmbalagens = async () => {
        if (!product.id) return;
        const { data } = await supabase
            .from('embalagens')
            .select('id, nome, quantidade_interna, tipo_embalagem, unidade_interna')
            .eq('produto_id', parseInt(product.id))
            .eq('ativo', true)
            .order('quantidade_interna', { ascending: false });
        setEmbalagens(data || []);
    };

    // Helper to refresh batches
    // Consulta `lotes` direto (não `estoque_lotes`) porque lotes recem-criados
    // via BatchList nao geram linha em estoque_lotes ate ter entrada real
    // de saldo. Espelha o filtro do modal: produto_id + loja_id.
    const refreshBatches = async () => {
        if (!product.id) return;
        let query = supabase
            .from('lotes')
            .select('id, codigo, data_validade, data_fabricacao, created_at')
            .eq('produto_id', parseInt(product.id));
        if (selectedStore?.id) {
            query = query.eq('loja_id', selectedStore.id);
        }
        const { data } = await query;

        if (data) {
            setBatches((data as any[]).map((l: any) => ({
                id: l.id,
                codigo: l.codigo || 'N/A',
                data_validade: l.data_validade,
                data_fabricacao: l.data_fabricacao,
                created_at: l.created_at ?? null,
            })));
        }
    };



    // Fetch products
    useEffect(() => {
        const fetchProducts = async () => {
            const { data, error } = await supabase
                .from('produtos_master')
                .select('id, nome, categoria:categoria_id(nome), setor, foto_url, dias_validade')
                .eq('ativo', true)
                .order('nome');

            if (data) {
                setProducts(data.map(p => ({
                    id: String(p.id),
                    name: p.nome,
                    category: p.categoria?.nome || 'Geral',
                    location: p.setor || 'Geral',
                    storage: 'Estoque',
                    image_url: p.foto_url,
                    validity_days: p.dias_validade || 0
                })));
            }
        };
        fetchProducts();
    }, []);

    // Fetch batches when product is selected
    useEffect(() => {
        if (product.id) {
            const fetchBatches = async () => {
                // Consulta `lotes` direto (nao `estoque_lotes`): lotes recem-criados
                // via BatchList nao tem linha em estoque_lotes ate haver entrada real
                // de saldo, mas o operador precisa imprimir etiqueta com esse lote.
                let query = supabase
                    .from('lotes')
                    .select('id, codigo, data_validade, data_fabricacao, created_at')
                    .eq('produto_id', parseInt(product.id));
                if (selectedStore?.id) {
                    query = query.eq('loja_id', selectedStore.id);
                }
                const { data } = await query;

                if (data) {
                    setBatches((data as any[]).map((l: any) => ({
                        id: l.id,
                        codigo: l.codigo || 'N/A',
                        data_validade: l.data_validade,
                        data_fabricacao: l.data_fabricacao,
                        created_at: l.created_at ?? null,
                    })));
                } else {
                    setBatches([]);
                }
                setSelectedBatch(null);
            };

            const fetchEmbalagens = async () => {
                const { data } = await supabase
                    .from('embalagens')
                    .select('id, nome, quantidade_interna, tipo_embalagem, unidade_interna')
                    .eq('produto_id', parseInt(product.id))
                    .eq('ativo', true)
                    .order('quantidade_interna', { ascending: false });

                setEmbalagens(data || []);
                setSelectedEmbalagem(null);
            };

            fetchBatches();
            fetchEmbalagens();
        } else {
            setBatches([]);
            setEmbalagens([]);
        }
    }, [product.id, selectedStore?.id]);

    const handleSelectProduct = (currentValue: string) => {
        const selected = products.find((p) => p.name === currentValue);
        if (selected) {
            setProduct(selected);
        }
        setOpen(false);
    };

    const handleBack = () => {
        if (isEmbedded) {
            // In embedded mode, maybe just reset selection?
            setProduct(EMPTY_PRODUCT);
        } else {
            navigate(-1);
        }
    };

    // Trigger print when uids change and we are actively trying to print
    useEffect(() => {
        if (isPrinting && printUids.length > 0) {
            // Give React a frame to render the DOM
            requestAnimationFrame(() => {
                setTimeout(() => {
                    window.print();
                    setIsPrinting(false);
                }, 500);
            });
        }
    }, [printUids, isPrinting]);

    const handlePrint = async () => {
        const parsedQuantity = typeof printQuantity === 'string' ? parseInt(printQuantity) : printQuantity;
        const numLabels = isNaN(parsedQuantity as number) || (parsedQuantity as number) <= 0 ? 0 : parsedQuantity as number;

        if (numLabels <= 0) {
            toast({ title: "Atenção", description: "Coloque uma quantidade válida maior que zero.", variant: "destructive" });
            return;
        }

        // Generate unique IDs for each label to print
        // Use a fallback for non-secure contexts (like HTTP on local network) where crypto.randomUUID is not available
        const newUids = Array.from({ length: numLabels }).map(() => {
            if (typeof crypto !== 'undefined' && crypto.randomUUID) {
                return crypto.randomUUID().split('-')[0];
            }
            // Fallback for HTTP connections (e.g. accessing via local IP)
            return Math.random().toString(36).substring(2, 10);
        });

        // Persistir cada UID em etiquetas_qr ANTES de imprimir (rastreabilidade fim-a-fim).
        // Apenas para etiqueta de produto — labels "loja"/"aberto" não têm QR rastreável.
        if (labelType === "produto" && product.id) {
            const { data: { user } } = await supabase.auth.getUser();
            const produtoMasterId = parseInt(product.id);
            // Fonte da verdade: 3 controles independentes (tipo + unidade + qty).
            // selectedEmbalagem é só preset opcional do catálogo (atalho).
            const qtyInterna = quantidadeInterna || 1;
            const tipoEmb = (tipoEmbalagem || 'caixa').toLowerCase().trim();
            const unidadeInt = (unidadeInterna || 'un').toLowerCase().trim();
            const lojaOrigem = selectedStore?.id ?? null;

            const rows = newUids.map(uid => ({
                uid,
                produto_master_id: produtoMasterId,
                lote_id: selectedBatch?.id || null,
                tipo_embalagem: tipoEmb,
                embalagem_nome: unidadeInt,
                quantidade_interna: qtyInterna,
                // Container nasce cheio — saldo disponivel = capacidade inicial.
                // Sem isso, RPC bipar_retirada_avulsa recebe NULL e comportamento fica indefinido.
                quantidade_disponivel: qtyInterna,
                consumida_inteira: false,
                produto_nome_snapshot: product.name,
                lote_codigo_snapshot: selectedBatch?.codigo || null,
                lote_validade_snapshot: selectedBatch?.data_validade || null,
                loja_origem_id: lojaOrigem,
                loja_atual_id: lojaOrigem,
                gerada_por: user?.id ?? null,
                gerada_at: new Date().toISOString(),
                qr_payload: {
                    p: produtoMasterId,
                    l: selectedBatch?.id || '',
                    c: selectedBatch?.codigo || '',
                    n: unidadeInt,
                    t: tipoEmb,
                    q: qtyInterna,
                    u: uid,
                },
            }));

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const { error } = await (supabase.from('etiquetas_qr' as any) as any).insert(rows);
            if (error) {
                console.error('[etiquetas_qr] insert falhou:', error);
                toast({
                    title: "Falha ao registrar etiquetas",
                    description: `Impressão abortada para evitar etiqueta órfã. ${error.message}`,
                    variant: "destructive",
                });
                return;
            }
        }

        setPrintUids(newUids);
        setIsPrinting(true);
    };

    // Esconde lotes antigos da seleção (impressos por engano). Toggle revela todos.
    const recentBatches = batches.filter(b => isLoteRecente(b.data_fabricacao, b.created_at));
    const hiddenOldCount = batches.length - recentBatches.length;
    const visibleBatches = showOldBatches ? batches : recentBatches;

    return (
        <div className={cn("flex flex-col h-full w-full gap-6 animate-in fade-in duration-500", !isEmbedded && "p-4 md:p-8")}>

            {/* Header Section - Hide if Embedded */}
            {!isEmbedded && (
                <div className="flex flex-col md:flex-row items-center justify-between gap-4 bg-white/50 dark:bg-zinc-900/50 p-6 rounded-3xl border border-[#57715B]/10 backdrop-blur-md print:hidden">
                    <div className="flex items-center gap-4">
                        <div className="h-12 w-12 rounded-2xl bg-[#57715B]/10 flex items-center justify-center">
                            <Printer className="h-6 w-6 text-[#57715B]" />
                        </div>
                        <div>
                            <h1 className="text-2xl font-bold text-[#57715B] dark:text-[#E6DCCF]">Impressão de Etiquetas</h1>
                            <p className="text-sm text-muted-foreground">Selecione o produto e lote para gerar a etiqueta</p>
                        </div>
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                        <Button
                            data-mia-action="abrir-auditoria-etiquetas"
                            variant="outline"
                            onClick={() => navigate('/etiquetas/auditoria')}
                            className="gap-2 text-[#57715B] border-[#57715B]/30 hover:bg-[#57715B]/10"
                        >
                            <ScanLine className="w-4 h-4" />
                            Auditoria
                        </Button>
                        <Button
                            data-mia-action="abrir-rastreabilidade-lotes"
                            variant="outline"
                            onClick={() => navigate('/lotes/rastreabilidade')}
                            className="gap-2 text-[#57715B] border-[#57715B]/30 hover:bg-[#57715B]/10"
                        >
                            <Search className="w-4 h-4" />
                            Rastreabilidade & Logs
                        </Button>
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 print:hidden">

                {/* SETTINGS PANEL (Left) */}
                <div className="lg:col-span-4 space-y-4">
                    <Card className="border-[#57715B]/20 shadow-lg bg-white/80 dark:bg-zinc-900/80 backdrop-blur-sm">
                        <CardContent className="p-6 space-y-6">

                            <div className="flex flex-col space-y-4 pb-6 border-b border-[#57715B]/10">
                                <div className="space-y-2">
