                                        fontSize: getStoreLabelFontSize(storeText),
                                        fontWeight: 900,
                                        textTransform: 'uppercase',
                                        textAlign: 'center',
                                        lineHeight: 1.15,
                                        wordBreak: 'break-word',
                                        overflowWrap: 'break-word',
                                        whiteSpace: 'pre-line',
                                        width: '100%',
                                        margin: 0,
                                        padding: '0 1mm',
                                    }}>
                                        {storeText}
                                    </h1>
                                </div>
                            );
                        })}

                        {/* Label 3: Produto Aberto */}
                        {labelType === "aberto" && printUids.map((uid, index) => (
                            <div key={uid} className={cn("label-container", index < printUids.length - 1 ? "page-break" : "")} style={{ display: 'flex', flexDirection: 'column', padding: '2mm' }}>
                                <div style={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', boxSizing: 'border-box', backgroundColor: 'white', color: 'black', fontFamily: 'Arial' }}>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Produto:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginBottom: '1mm' }}></div></div>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Fornecedor:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginBottom: '1mm' }}></div></div>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Lote:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginBottom: '1mm' }}></div></div>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Manipulado:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginRight: '1mm', marginBottom: '1mm' }}></div>/<div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '1mm', marginRight: '1mm', marginBottom: '1mm' }}></div>/<div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '1mm', marginBottom: '1mm' }}></div></div>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Validade:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginRight: '1mm', marginBottom: '1mm' }}></div>/<div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '1mm', marginRight: '1mm', marginBottom: '1mm' }}></div>/<div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '1mm', marginBottom: '1mm' }}></div></div>
                                    <div style={{ display: 'flex', alignItems: 'flex-end', fontSize: '10pt', fontWeight: 'bold' }}><span style={{ whiteSpace: 'nowrap' }}>Responsável:</span><div style={{ flex: 1, borderBottom: '1px solid black', marginLeft: '2mm', marginBottom: '1mm' }}></div></div>
                                </div>
                            </div>
                        ))}
                    </div>,
                    document.body
                )
            }
        </div >
    );
}

export default function LabelPrinting() {
    return (
        <div className="min-h-screen bg-gradient-to-b from-gray-100 to-gray-200 dark:from-zinc-900 dark:to-zinc-950">
            <LabelPrintingContent />
        </div>
    );
}

