-- Fix em bipar_etiqueta: no backfill, se o lote_uuid do payload nao existe em lotes,
-- resolve por codigo+validade via find_or_create_lote ou usa NULL.
-- Antes: INSERT com UUID morto -> FK rejeitava -> movimentacoes FK cascateava erro.
CREATE OR REPLACE FUNCTION public.bipar_etiqueta(p_uid text, p_etapa text, p_contexto jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_etiqueta public.etiquetas_qr%ROWTYPE;
  v_user_id uuid := auth.uid();
  v_user_nome text; v_status_anterior text; v_status_novo text; v_loja_id integer;
  v_alertas jsonb := '[]'::jsonb; v_referencia_tipo text; v_referencia_id text;
  v_payload jsonb; v_pid_text text; v_pid_int integer; v_lote_uuid uuid;
  v_produto_nome text; v_lote_codigo text; v_lote_validade date; v_qty_interna numeric;
BEGIN
  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa invalida: ' || p_etapa); END IF;
  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome FROM auth.users WHERE id = v_user_id;
  v_loja_id := NULLIF(p_contexto->>'loja_id','')::integer;
  v_referencia_tipo := p_contexto->>'referencia_tipo'; v_referencia_id := p_contexto->>'referencia_id';
  v_payload := p_contexto->'payload';
  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;
  IF NOT FOUND THEN
    IF v_payload IS NULL THEN RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e sem payload para backfill'); END IF;
    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
    IF v_pid_text IS NULL OR v_pid_text = '' THEN RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto'); END IF;
    v_pid_int := v_pid_text::integer;
    v_lote_uuid := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);
    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
    -- Resolve lote_id seguro: UUID morto -> tenta por codigo+validade -> NULL
    IF v_lote_uuid IS NOT NULL THEN
      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade FROM public.lotes WHERE id = v_lote_uuid;
      IF NOT FOUND THEN
        v_lote_codigo  := NULLIF(COALESCE(v_payload->>'lote', v_payload->>'lc'), '');
        v_lote_validade := NULLIF(COALESCE(v_payload->>'val', v_payload->>'v'), '')::date;
        IF v_lote_codigo IS NOT NULL AND v_lote_validade IS NOT NULL THEN
          v_lote_uuid := public.find_or_create_lote(v_pid_int, v_lote_codigo, v_lote_validade, NULL, NULL);
        ELSE v_lote_uuid := NULL; END IF;
      END IF;
    END IF;
    INSERT INTO public.etiquetas_qr (uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna, quantidade_disponivel, consumida_inteira, produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot, loja_origem_id, loja_atual_id, status, tipo_embalagem, foi_separada, separada_at, separada_por, foi_conferida, conferida_at, conferida_por, backfilled, qr_payload)
    VALUES (p_uid, v_pid_int, v_lote_uuid, COALESCE(v_payload->>'emb', v_payload->>'n'), v_qty_interna, v_qty_interna, false, v_produto_nome, v_lote_codigo, v_lote_validade, NULL, v_loja_id, CASE p_etapa WHEN 'separacao' THEN 'gerada' WHEN 'conferencia' THEN 'gerada' WHEN 'entrada' THEN 'recebida' WHEN 'saida' THEN 'em_transito' WHEN 'consumo' THEN 'consumida' WHEN 'descarte' THEN 'descartada' END, COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'), (p_etapa = 'separacao'), CASE WHEN p_etapa = 'separacao' THEN NOW() ELSE NULL END, CASE WHEN p_etapa = 'separacao' THEN v_user_id ELSE NULL END, (p_etapa = 'conferencia'), CASE WHEN p_etapa = 'conferencia' THEN NOW() ELSE NULL END, CASE WHEN p_etapa = 'conferencia' THEN v_user_id ELSE NULL END, true, v_payload) RETURNING * INTO v_etiqueta;
    v_alertas := v_alertas || jsonb_build_array('Etiqueta antiga registrada retroativamente (backfill)');
    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'backfilled', 'backfill', NULL, v_etiqueta.status, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, jsonb_build_object('etapa_origem', p_etapa, 'payload', v_payload));
    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', NULL, 'status_novo', v_etiqueta.status, 'alertas', v_alertas, 'backfilled', true);
  END IF;
  v_status_anterior := v_etiqueta.status;
  IF v_etiqueta.status = 'descartada' THEN RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada' || CASE WHEN v_etiqueta.replaced_by_uid IS NOT NULL THEN ' (substituida por ' || v_etiqueta.replaced_by_uid || ')' ELSE '' END, 'etiqueta', to_jsonb(v_etiqueta)); END IF;
  IF v_etiqueta.lote_validade_snapshot IS NOT NULL AND v_etiqueta.lote_validade_snapshot < CURRENT_DATE THEN v_alertas := v_alertas || jsonb_build_array(format('LOTE VENCIDO em %s', to_char(v_etiqueta.lote_validade_snapshot,'DD/MM/YYYY'))); END IF;
  IF p_etapa = 'separacao' THEN
    IF v_etiqueta.foi_separada THEN RETURN jsonb_build_object('ok', false, 'erro', format('Etiqueta %s ja esta com status "separada" — bip duplicado nesta etapa', p_uid), 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior); END IF;
    UPDATE public.etiquetas_qr SET foi_separada = TRUE, separada_at = NOW(), separada_por = v_user_id, loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'bipada_separacao', 'separacao', v_status_anterior, v_status_anterior, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior, 'alertas', v_alertas, 'backfilled', false);
  END IF;
  IF p_etapa = 'conferencia' THEN
    IF v_etiqueta.foi_conferida THEN RETURN jsonb_build_object('ok', false, 'erro', format('Etiqueta %s ja esta com status "conferida" — bip duplicado nesta etapa', p_uid), 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior); END IF;
    UPDATE public.etiquetas_qr SET foi_conferida = TRUE, conferida_at = NOW(), conferida_por = v_user_id, loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'bipada_conferencia', 'conferencia', v_status_anterior, v_status_anterior, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
    RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_anterior, 'alertas', v_alertas, 'backfilled', false);
  END IF;
  v_status_novo := CASE p_etapa
    WHEN 'saida' THEN CASE WHEN v_etiqueta.status IN ('gerada','recebida','aberta','consumida') THEN 'em_transito' ELSE NULL END
    WHEN 'entrada' THEN CASE WHEN v_etiqueta.status IN ('em_transito','gerada','aberta','consumida') THEN 'recebida' WHEN v_etiqueta.status = 'recebida' AND v_loja_id IS DISTINCT FROM v_etiqueta.loja_atual_id THEN 'recebida' ELSE NULL END
    WHEN 'consumo' THEN 'consumida'
    WHEN 'descarte' THEN 'descartada'
  END;
  IF v_status_novo IS NULL THEN RETURN jsonb_build_object('ok', false, 'erro', format('Etiqueta %s ja esta com status "%s" — bip duplicado nesta etapa', p_uid, v_status_anterior), 'etiqueta', to_jsonb(v_etiqueta)); END IF;
  UPDATE public.etiquetas_qr SET status = v_status_novo, loja_atual_id = COALESCE(v_loja_id, loja_atual_id) WHERE uid = p_uid RETURNING * INTO v_etiqueta;
  INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo, loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata) VALUES (p_uid, 'bipada_' || p_etapa, p_etapa, v_status_anterior, v_status_novo, v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id, p_contexto - 'payload');
  RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta), 'status_anterior', v_status_anterior, 'status_novo', v_status_novo, 'alertas', v_alertas, 'backfilled', false);
END;
$function$;

content.content:
1	-- =============================================================================
2	-- EXPOSITORA (Pronta Entrega v2) — controle do estoque exposto no salão
3	--
4	-- Modelo: estoque (câmara fria/congelado) → EXPOSITORA (vitrines/balcão) → venda.
5	-- Total em loja = estoque.quantidade_atual + expositora_estoque.quantidade.
6	--
7	-- Ponto único de integração: trigger em movimentacoes. Toda saída de estoque
8	-- com motivo da família "exposição" credita a expositora NA MESMA TRANSAÇÃO:
9	--   · 'exposicao'                 → movimentação manual (página Pronta Entrega)
10	--   · 'saida_inteira_exposicao'   → bip de container inteiro (bipar_etiqueta etapa 'exposicao')
11	--   · 'retirada_avulsa_exposicao' → retirada parcial com destino expositora
12	--
13	-- Saldo da expositora PODE ficar negativo por design — mostra o furo de
14	-- processo (venda/perda sem registro de subida pra vitrine). Fase 2 (Degust)
15	-- vai lançar tipo='venda' no ledger.
16	--
17	-- Nada destrutivo: pronta_entrega_stock/logs permanecem como histórico.
18	-- =============================================================================
19	
20	-- ─────────────────────────────────────────────────────────────────────────────
21	-- 1) Tabelas: saldo + ledger append-only
22	-- ─────────────────────────────────────────────────────────────────────────────
23	
24	CREATE TABLE IF NOT EXISTS public.expositora_estoque (
25	  id                bigserial PRIMARY KEY,
26	  produto_master_id integer NOT NULL REFERENCES public.produtos_master(id),
27	  loja_id           integer NOT NULL REFERENCES public.lojas(id),
28	  quantidade        numeric NOT NULL DEFAULT 0,  -- pode ser negativa (furo de processo visível)
29	  updated_at        timestamptz NOT NULL DEFAULT now(),
30	  UNIQUE (produto_master_id, loja_id)
31	);
32	
33	CREATE INDEX IF NOT EXISTS idx_expositora_estoque_loja
34	  ON public.expositora_estoque (loja_id);
35	
36	CREATE TABLE IF NOT EXISTS public.expositora_movimentacoes (
37	  id                bigserial PRIMARY KEY,
38	  produto_master_id integer NOT NULL REFERENCES public.produtos_master(id),
39	  loja_id           integer NOT NULL REFERENCES public.lojas(id),
40	  tipo              text    NOT NULL CHECK (tipo IN ('entrada','saida','ajuste','venda')),
41	  quantidade        numeric NOT NULL,            -- magnitude do movimento (sempre > 0)
42	  saldo_anterior    numeric NOT NULL,
43	  saldo_novo        numeric NOT NULL,
44	  motivo            text    NOT NULL,
45	  movimentacao_id   integer REFERENCES public.movimentacoes(id) ON DELETE SET NULL,
46	  etiqueta_qr_uid   text,                        -- trace; sem FK de propósito (etiquetas podem ser limpas)
47	  usuario_id        uuid,
48	  usuario_nome      text,
49	  observacoes       text,
50	  created_at        timestamptz NOT NULL DEFAULT now()
51	);
52	
53	CREATE INDEX IF NOT EXISTS idx_expositora_mov_loja_produto_data
54	  ON public.expositora_movimentacoes (loja_id, produto_master_id, created_at DESC);
55	CREATE INDEX IF NOT EXISTS idx_expositora_mov_loja_data
56	  ON public.expositora_movimentacoes (loja_id, created_at DESC);
57	
58	-- RLS: leitura pra authenticated; escrita SÓ via funções SECURITY DEFINER
59	ALTER TABLE public.expositora_estoque        ENABLE ROW LEVEL SECURITY;
60	ALTER TABLE public.expositora_movimentacoes  ENABLE ROW LEVEL SECURITY;
61	
62	DROP POLICY IF EXISTS expositora_estoque_select ON public.expositora_estoque;
63	CREATE POLICY expositora_estoque_select
64	  ON public.expositora_estoque FOR SELECT TO authenticated USING (true);
65	
66	DROP POLICY IF EXISTS expositora_movimentacoes_select ON public.expositora_movimentacoes;
67	CREATE POLICY expositora_movimentacoes_select
68	  ON public.expositora_movimentacoes FOR SELECT TO authenticated USING (true);
69	
70	-- ─────────────────────────────────────────────────────────────────────────────
71	-- 2) Nova etapa 'exposicao' no CHECK de etiquetas_qr_eventos
72	-- ─────────────────────────────────────────────────────────────────────────────
73	
74	ALTER TABLE public.etiquetas_qr_eventos
75	  DROP CONSTRAINT IF EXISTS etiquetas_qr_eventos_etapa_check;
76	ALTER TABLE public.etiquetas_qr_eventos
77	  ADD CONSTRAINT etiquetas_qr_eventos_etapa_check CHECK (etapa = ANY (ARRAY[
78	    'geracao'::text, 'separacao'::text, 'conferencia'::text, 'entrada'::text,
79	    'saida'::text, 'consumo'::text, 'descarte'::text, 'reposicao'::text,
80	    'backfill'::text, 'exposicao'::text
81	  ]));
82	
83	-- ─────────────────────────────────────────────────────────────────────────────
84	-- 3) Helper interno: aplica delta no saldo da expositora + grava ledger
85	--    (lock por linha; cria a linha zerada se não existir)
86	-- ─────────────────────────────────────────────────────────────────────────────
87	
88	CREATE OR REPLACE FUNCTION public.fn_expositora_aplicar(
89	  p_produto_master_id integer,
90	  p_loja_id           integer,
91	  p_delta             numeric,   -- positivo soma, negativo subtrai
92	  p_tipo              text,      -- 'entrada' | 'saida' | 'ajuste' | 'venda'
93	  p_motivo            text,
94	  p_movimentacao_id   integer DEFAULT NULL,
95	  p_etiqueta_qr_uid   text    DEFAULT NULL,
96	  p_usuario_id        uuid    DEFAULT NULL,
97	  p_usuario_nome      text    DEFAULT NULL,
98	  p_observacoes       text    DEFAULT NULL
99	) RETURNS numeric
100	LANGUAGE plpgsql
101	SECURITY DEFINER
102	SET search_path TO 'public'
103	AS $$
104	DECLARE
105	  v_saldo_anterior numeric;
106	  v_saldo_novo     numeric;
107	BEGIN
108	  IF p_delta IS NULL OR p_delta = 0 THEN
109	    SELECT quantidade INTO v_saldo_anterior
110	      FROM public.expositora_estoque
111	     WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;
112	    RETURN COALESCE(v_saldo_anterior, 0);
113	  END IF;
114	
115	  -- garante a linha e trava pra leitura consistente do saldo
116	  INSERT INTO public.expositora_estoque (produto_master_id, loja_id, quantidade)
117	  VALUES (p_produto_master_id, p_loja_id, 0)
118	  ON CONFLICT (produto_master_id, loja_id) DO NOTHING;
119	
120	  SELECT quantidade INTO v_saldo_anterior
121	    FROM public.expositora_estoque
122	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
123	   FOR UPDATE;
124	
125	  v_saldo_novo := v_saldo_anterior + p_delta;
126	
127	  UPDATE public.expositora_estoque
128	     SET quantidade = v_saldo_novo, updated_at = now()
129	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;
130	
131	  INSERT INTO public.expositora_movimentacoes (
132	    produto_master_id, loja_id, tipo, quantidade, saldo_anterior, saldo_novo,
133	    motivo, movimentacao_id, etiqueta_qr_uid, usuario_id, usuario_nome, observacoes
134	  ) VALUES (
135	    p_produto_master_id, p_loja_id, p_tipo, ABS(p_delta), v_saldo_anterior, v_saldo_novo,
136	    p_motivo, p_movimentacao_id, p_etiqueta_qr_uid, p_usuario_id, p_usuario_nome, p_observacoes
137	  );
138	
139	  RETURN v_saldo_novo;
140	END;
141	$$;
142	
143	REVOKE EXECUTE ON FUNCTION public.fn_expositora_aplicar(integer,integer,numeric,text,text,integer,text,uuid,text,text) FROM PUBLIC, anon;
144	
145	-- ─────────────────────────────────────────────────────────────────────────────
146	-- 4) Trigger em movimentacoes: saída com motivo de exposição → credita expositora
147	--    (mesma transação que o débito de estoque feito por atualizar_estoque_e_alertas)
148	-- ─────────────────────────────────────────────────────────────────────────────
149	
150	CREATE OR REPLACE FUNCTION public.tg_movimentacoes_expositora()
151	RETURNS trigger
152	LANGUAGE plpgsql
153	SECURITY DEFINER
154	SET search_path TO 'public'
155	AS $$
156	DECLARE
157	  v_user_id   uuid := auth.uid();
158	  v_user_nome text;
159	BEGIN
160	  IF NEW.tipo_movimentacao <> 'saida'
161	     OR COALESCE(NEW.motivo,'') NOT IN ('exposicao','saida_inteira_exposicao','retirada_avulsa_exposicao') THEN
162	    RETURN NEW;
163	  END IF;
164	  IF NEW.produto_master_id IS NULL OR NEW.loja_id IS NULL THEN
165	    RETURN NEW;
166	  END IF;
167	
168	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome
169	    FROM auth.users WHERE id = v_user_id;
170	
171	  PERFORM public.fn_expositora_aplicar(
172	    NEW.produto_master_id, NEW.loja_id, NEW.quantidade,
173	    'entrada', NEW.motivo, NEW.id, NEW.etiqueta_qr_uid,
174	    v_user_id, v_user_nome, NEW.observacoes
175	  );
176	
177	  RETURN NEW;
178	END;
179	$$;
180	
181	DROP TRIGGER IF EXISTS trg_movimentacoes_expositora ON public.movimentacoes;
182	CREATE TRIGGER trg_movimentacoes_expositora
183	AFTER INSERT ON public.movimentacoes
184	FOR EACH ROW EXECUTE FUNCTION public.tg_movimentacoes_expositora();
185	
186	-- ─────────────────────────────────────────────────────────────────────────────
187	-- 5) RPC: mover manualmente do estoque pra expositora (página Pronta Entrega)
188	-- ─────────────────────────────────────────────────────────────────────────────
189	
190	CREATE OR REPLACE FUNCTION public.mover_para_expositora(
191	  p_produto_master_id integer,
192	  p_loja_id           integer,
193	  p_quantidade        numeric,
194	  p_observacoes       text DEFAULT NULL
195	) RETURNS jsonb
196	LANGUAGE plpgsql
197	SECURITY DEFINER
198	SET search_path TO 'public'
199	AS $$
200	DECLARE
201	  v_estoque_anterior numeric;
202	  v_estoque_novo     numeric;
203	  v_expositora       numeric;
204	  v_alertas          jsonb := '[]'::jsonb;
205	  v_restante         numeric;
206	  v_baixa            numeric;
207	  r                  RECORD;
208	BEGIN
209	  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
210	    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade deve ser maior que zero');
211	  END IF;
212	  IF p_loja_id IS NULL OR p_loja_id = 1 THEN
213	    RETURN jsonb_build_object('ok', false, 'erro', 'Expositora é por loja — fábrica não tem vitrine');
214	  END IF;
215	  IF NOT EXISTS (SELECT 1 FROM public.produtos_master WHERE id = p_produto_master_id AND ativo = true) THEN
216	    RETURN jsonb_build_object('ok', false, 'erro', 'Produto não encontrado ou inativo');
217	  END IF;
218	
219	  SELECT quantidade_atual INTO v_estoque_anterior
220	    FROM public.estoque
221	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
222	   FOR UPDATE;
223	
224	  v_estoque_anterior := COALESCE(v_estoque_anterior, 0);
225	  v_estoque_novo     := v_estoque_anterior - p_quantidade;
226	
227	  IF v_estoque_novo < 0 THEN
228	    v_alertas := v_alertas || jsonb_build_array(
229	      format('Estoque da câmara ficou negativo (%s) — confira a contagem', v_estoque_novo));
230	  END IF;
231	
232	  -- Baixa FIFO em estoque_lotes (validade mais próxima primeiro) pra manter
233	  -- lotes ↔ estoque em sincronia. Sem isso, a próxima edição direta de
234	  -- estoque_lotes dispararia sync_estoque_from_lotes, que REVERTERIA esta
235	  -- baixa via 'sync_lote_auto' (produto contado em dobro: câmara + vitrine).
236	  -- Guard transacional impede o reconciliador de reagir a ESTA baixa.
237	  PERFORM set_config('app.skip_lote_reconcile', '1', true);
238	  v_restante := p_quantidade;
239	  FOR r IN
240	    SELECT el.id, el.quantidade
241	      FROM public.estoque_lotes el
242	      LEFT JOIN public.lotes l ON l.id = el.lote_id
243	     WHERE el.produto_id = p_produto_master_id
244	       AND el.loja_id = p_loja_id
245	       AND el.quantidade > 0
246	     ORDER BY l.data_validade NULLS LAST, el.id
247	     FOR UPDATE OF el
248	  LOOP
249	    EXIT WHEN v_restante <= 0;
250	    v_baixa := LEAST(r.quantidade, v_restante);
251	    UPDATE public.estoque_lotes SET quantidade = quantidade - v_baixa WHERE id = r.id;
252	    v_restante := v_restante - v_baixa;
253	  END LOOP;
254	
255	  -- débito do estoque (trigger atualizar_estoque_e_alertas) +
256	  -- crédito da expositora (trigger tg_movimentacoes_expositora) — atômico
257	  INSERT INTO public.movimentacoes (
258	    produto_master_id, tipo_movimentacao, quantidade,
259	    quantidade_anterior, quantidade_nova, motivo, observacoes,
260	    data_movimentacao, loja_id
261	  ) VALUES (
262	    p_produto_master_id, 'saida', p_quantidade,
263	    v_estoque_anterior, v_estoque_novo, 'exposicao',
264	    COALESCE(p_observacoes, 'Movido para expositora'),
265	    now(), p_loja_id
266	  );
267	
268	  SELECT quantidade INTO v_expositora
269	    FROM public.expositora_estoque
270	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;
271	
272	  RETURN jsonb_build_object(
273	    'ok', true,
274	    'estoque_anterior',  v_estoque_anterior,
275	    'estoque_novo',      v_estoque_novo,
276	    'expositora_saldo',  COALESCE(v_expositora, 0),
277	    'alertas',           v_alertas
278	  );
279	END;
280	$$;
281	
282	REVOKE EXECUTE ON FUNCTION public.mover_para_expositora(integer,integer,numeric,text) FROM PUBLIC, anon;
283	GRANT  EXECUTE ON FUNCTION public.mover_para_expositora(integer,integer,numeric,text) TO authenticated;
284	
285	-- ─────────────────────────────────────────────────────────────────────────────
286	-- 6) RPC: ajuste da expositora com motivo (perda, vencido, degustação,
287	--    consumo interno, recontagem/contagem inicial). NÃO mexe no estoque.
288	-- ─────────────────────────────────────────────────────────────────────────────
289	
290	CREATE OR REPLACE FUNCTION public.ajustar_expositora(
291	  p_produto_master_id integer,
292	  p_loja_id           integer,
293	  p_quantidade        numeric,            -- delta (modo 'delta') ou saldo alvo (modo 'absoluto')
294	  p_modo              text DEFAULT 'delta',
295	  p_motivo            text DEFAULT 'outro',
296	  p_observacoes       text DEFAULT NULL
297	) RETURNS jsonb
298	LANGUAGE plpgsql
299	SECURITY DEFINER
300	SET search_path TO 'public'
301	AS $$
302	DECLARE
303	  v_user_id      uuid := auth.uid();
304	  v_user_nome    text;
305	  v_saldo_atual  numeric;
306	  v_delta        numeric;
307	  v_saldo_novo   numeric;
308	BEGIN
309	  IF p_modo NOT IN ('delta','absoluto') THEN
310	    RETURN jsonb_build_object('ok', false, 'erro', 'Modo inválido: ' || COALESCE(p_modo,'<null>'));
311	  END IF;
312	  IF p_motivo NOT IN ('perda','vencido','degustacao','consumo_interno','recontagem','contagem_inicial','outro') THEN
313	    RETURN jsonb_build_object('ok', false, 'erro', 'Motivo inválido: ' || COALESCE(p_motivo,'<null>'));
314	  END IF;
315	  IF p_quantidade IS NULL THEN
316	    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade obrigatória');
317	  END IF;
318	  IF p_loja_id IS NULL OR p_loja_id = 1 THEN
319	    RETURN jsonb_build_object('ok', false, 'erro', 'Expositora é por loja — fábrica não tem vitrine');
320	  END IF;
321	  IF NOT EXISTS (SELECT 1 FROM public.produtos_master WHERE id = p_produto_master_id) THEN
322	    RETURN jsonb_build_object('ok', false, 'erro', 'Produto não encontrado');
323	  END IF;
324	
325	  -- garante linha + trava antes de calcular delta (modo absoluto depende do saldo atual)
326	  INSERT INTO public.expositora_estoque (produto_master_id, loja_id, quantidade)
327	  VALUES (p_produto_master_id, p_loja_id, 0)
328	  ON CONFLICT (produto_master_id, loja_id) DO NOTHING;
329	
330	  SELECT quantidade INTO v_saldo_atual
331	    FROM public.expositora_estoque
332	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
333	   FOR UPDATE;
334	
335	  v_delta := CASE WHEN p_modo = 'absoluto' THEN p_quantidade - v_saldo_atual ELSE p_quantidade END;
336	
337	  IF v_delta = 0 THEN
338	    RETURN jsonb_build_object('ok', true, 'saldo', v_saldo_atual, 'delta', 0,
339	                              'mensagem', 'Saldo já estava no valor informado');
340	  END IF;
341	
342	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome
343	    FROM auth.users WHERE id = v_user_id;
344	
345	  v_saldo_novo := public.fn_expositora_aplicar(
346	    p_produto_master_id, p_loja_id, v_delta,
347	    'ajuste', p_motivo, NULL, NULL,
348	    v_user_id, v_user_nome, p_observacoes
349	  );
350	
351	  RETURN jsonb_build_object('ok', true, 'saldo_anterior', v_saldo_atual,
352	                            'saldo', v_saldo_novo, 'delta', v_delta);
353	END;
354	$$;
355	
356	REVOKE EXECUTE ON FUNCTION public.ajustar_expositora(integer,integer,numeric,text,text,text) FROM PUBLIC, anon;
357	GRANT  EXECUTE ON FUNCTION public.ajustar_expositora(integer,integer,numeric,text,text,text) TO authenticated;
358	
359	-- ─────────────────────────────────────────────────────────────────────────────
360	-- 7) bipar_etiqueta: nova etapa 'exposicao' — container inteiro vai pra vitrine.
361	--    Etiqueta → 'consumida' (desembalada no salão); movimentação de saída do
362	--    estoque criada AQUI DENTRO (motivo 'saida_inteira_exposicao') pra garantir
363	--    atomicidade etiqueta + estoque + lotes + expositora.
364	--    Resto da função idêntico à versão em produção.
365	-- ─────────────────────────────────────────────────────────────────────────────
366	
367	CREATE OR REPLACE FUNCTION public.bipar_etiqueta(p_uid text, p_etapa text, p_contexto jsonb DEFAULT '{}'::jsonb)
368	 RETURNS jsonb
369	 LANGUAGE plpgsql
370	 SECURITY DEFINER
371	 SET search_path TO 'public'
372	AS $function$
373	DECLARE
374	  v_etiqueta public.etiquetas_qr%ROWTYPE;
375	  v_user_id uuid := auth.uid();
376	  v_user_nome text;
377	  v_status_anterior text;
378	  v_status_novo text;
379	  v_loja_id integer;
380	  v_alertas jsonb := '[]'::jsonb;
381	  v_referencia_tipo text;
382	  v_referencia_id text;
383	  v_payload jsonb;
384	  v_pid_text text;
385	  v_pid_int integer;
386	  v_lote_uuid uuid;
387	  v_produto_nome text;
388	  v_lote_codigo text;
389	  v_lote_validade date;
390	  v_qty_interna numeric;
391	  -- exposição
392	  v_loja_eff integer;
393	  v_qtd_expor numeric;
394	  v_est_ant numeric;
395	BEGIN
396	  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte','exposicao') THEN
397	    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa invalida: ' || p_etapa);
398	  END IF;
399	
400	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome
401	    FROM auth.users WHERE id = v_user_id;
402	
403	  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
404	  v_referencia_tipo := p_contexto->>'referencia_tipo';
405	  v_referencia_id   := p_contexto->>'referencia_id';
406	  v_payload         := p_contexto->'payload';
407	
408	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;
409	
410	  -- ── BACKFILL: etiqueta nova (nunca registrada) ──────────────────────────────
411	  IF NOT FOUND THEN
412	    IF v_payload IS NULL THEN
413	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e sem payload para backfill');
414	    END IF;
415	
416	    -- exposição exige loja conhecida (não há etiqueta pra herdar loja_atual_id)
417	    IF p_etapa = 'exposicao' AND v_loja_id IS NULL THEN
418	      RETURN jsonb_build_object('ok', false, 'erro', 'Exposicao exige loja_id no contexto');
419	    END IF;
420	
421	    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
422	    IF v_pid_text IS NULL OR v_pid_text = '' THEN
423	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto');
424	    END IF;
425	    v_pid_int     := v_pid_text::integer;
426	    v_lote_uuid   := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
427	    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);
428	
429	    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
430	
431	    -- Resolve lote_id de forma segura: se UUID do payload nao existe, cria/encontra
432	    -- por codigo+validade ou usa NULL. Nunca insere UUID morto (causa FK error).
433	    IF v_lote_uuid IS NOT NULL THEN
434	      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade
435	        FROM public.lotes WHERE id = v_lote_uuid;
436	      IF NOT FOUND THEN
437	        -- UUID morto: tenta resolver por snapshot no payload
438	        v_lote_codigo  := NULLIF(COALESCE(v_payload->>'lote', v_payload->>'lc'), '');
439	        v_lote_validade := NULLIF(COALESCE(v_payload->>'val',  v_payload->>'v'),  '')::date;
440	        IF v_lote_codigo IS NOT NULL AND v_lote_validade IS NOT NULL THEN
441	          v_lote_uuid := public.find_or_create_lote(
442	            v_pid_int, v_lote_codigo, v_lote_validade, NULL, NULL
443	          );
444	        ELSE
445	          v_lote_uuid := NULL;  -- sem como resolver; grava sem lote (FK permite NULL)
446	        END IF;
447	      END IF;
448	    END IF;
449	
450	    INSERT INTO public.etiquetas_qr (
451	      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
452	      quantidade_disponivel, consumida_inteira,
453	      produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
454	      loja_origem_id, loja_atual_id, status, tipo_embalagem,
455	      foi_separada, separada_at, separada_por,
456	      foi_conferida, conferida_at, conferida_por,
457	      backfilled, qr_payload
458	    ) VALUES (
459	      p_uid, v_pid_int, v_lote_uuid,
460	      COALESCE(v_payload->>'emb', v_payload->>'n'),
461	      v_qty_interna,
462	      CASE WHEN p_etapa = 'exposicao' THEN 0 ELSE v_qty_interna END,
463	      (p_etapa = 'exposicao'),
464	      v_produto_nome, v_lote_codigo, v_lote_validade,
465	      NULL, v_loja_id,
466	      CASE p_etapa
467	        WHEN 'separacao'  THEN 'gerada'
468	        WHEN 'conferencia' THEN 'gerada'
469	        WHEN 'entrada'    THEN 'recebida'
470	        WHEN 'saida'      THEN 'em_transito'
471	        WHEN 'consumo'    THEN 'consumida'
472	        WHEN 'descarte'   THEN 'descartada'
473	        WHEN 'exposicao'  THEN 'consumida'
474	      END,
475	      COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'),
476	      (p_etapa = 'separacao'),
477	      CASE WHEN p_etapa = 'separacao' THEN NOW() ELSE NULL END,
478	      CASE WHEN p_etapa = 'separacao' THEN v_user_id ELSE NULL END,
479	      (p_etapa = 'conferencia'),
480	      CASE WHEN p_etapa = 'conferencia' THEN NOW() ELSE NULL END,
481	      CASE WHEN p_etapa = 'conferencia' THEN v_user_id ELSE NULL END,
482	      true, v_payload
483	    ) RETURNING * INTO v_etiqueta;
484	
485	    -- exposição em backfill: registra a saída do estoque (crédito da expositora
486	    -- acontece via trigger tg_movimentacoes_expositora)
487	    IF p_etapa = 'exposicao' THEN
488	      SELECT quantidade_atual INTO v_est_ant
489	        FROM public.estoque
490	       WHERE produto_master_id = v_pid_int AND loja_id = v_loja_id
491	       FOR UPDATE;
492	      v_est_ant := COALESCE(v_est_ant, 0);
493	
494	      INSERT INTO public.movimentacoes (
495	        produto_master_id, tipo_movimentacao, quantidade,
496	        quantidade_anterior, quantidade_nova, motivo, observacoes,
497	        data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
498	      ) VALUES (
499	        v_pid_int, 'saida', v_qty_interna,
500	        v_est_ant, v_est_ant - v_qty_interna,
501	        'saida_inteira_exposicao',
502	        format('Exposicao na vitrine (backfill) — UID %s', p_uid),
503	        NOW(), v_loja_id, v_lote_uuid, p_uid
504	      );
505	    END IF;
506	
507	    v_alertas := v_alertas || jsonb_build_array('Etiqueta antiga registrada retroativamente (backfill)');
508	    INSERT INTO public.etiquetas_qr_eventos (
509	      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
510	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
511	    ) VALUES (
512	      p_uid, 'backfilled', 'backfill', NULL, v_etiqueta.status,
513	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
514	      jsonb_build_object('etapa_origem', p_etapa, 'payload', v_payload)
515	    );
516	
517	    RETURN jsonb_build_object(
518	      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
519	      'status_anterior', NULL, 'status_novo', v_etiqueta.status,
520	      'alertas', v_alertas, 'backfilled', true,
521	      'quantidade_exposta', CASE WHEN p_etapa = 'exposicao' THEN v_qty_interna ELSE NULL END
522	    );
523	  END IF;
524	  -- ── FIM BACKFILL ─────────────────────────────────────────────────────────────
525	
526	  v_status_anterior := v_etiqueta.status;
527	
528	  IF v_etiqueta.status = 'descartada' THEN
529	    RETURN jsonb_build_object(
530	      'ok', false, 'erro', 'Etiqueta descartada'
531	        || CASE WHEN v_etiqueta.replaced_by_uid IS NOT NULL
532	                THEN ' (substituida por ' || v_etiqueta.replaced_by_uid || ')'
533	                ELSE '' END,
534	      'etiqueta', to_jsonb(v_etiqueta)
535	    );
536	  END IF;
537	
538	  IF v_etiqueta.lote_validade_snapshot IS NOT NULL
539	     AND v_etiqueta.lote_validade_snapshot < CURRENT_DATE THEN
540	    v_alertas := v_alertas || jsonb_build_array(
541	      format('LOTE VENCIDO em %s', to_char(v_etiqueta.lote_validade_snapshot,'DD/MM/YYYY'))
542	    );
543	  END IF;
544	
545	  -- ── SEPARAÇÃO ────────────────────────────────────────────────────────────────
546	  IF p_etapa = 'separacao' THEN
547	    IF v_etiqueta.foi_separada THEN
548	      RETURN jsonb_build_object(
549	        'ok', false,
550	        'erro', format('Etiqueta %s ja esta com status "separada" — bip duplicado nesta etapa', p_uid),
551	        'etiqueta', to_jsonb(v_etiqueta),
552	        'status_anterior', v_status_anterior, 'status_novo', v_status_anterior
553	      );
554	    END IF;
555	    UPDATE public.etiquetas_qr
556	       SET foi_separada = TRUE, separada_at = NOW(), separada_por = v_user_id,
557	           loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
558	     WHERE uid = p_uid RETURNING * INTO v_etiqueta;
559	    INSERT INTO public.etiquetas_qr_eventos (
560	      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
561	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
562	    ) VALUES (
563	      p_uid, 'bipada_separacao', 'separacao', v_status_anterior, v_status_anterior,
564	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
565	      p_contexto - 'payload'
566	    );
567	    RETURN jsonb_build_object(
568	      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
569	      'status_anterior', v_status_anterior, 'status_novo', v_status_anterior,
570	      'alertas', v_alertas, 'backfilled', false
571	    );
572	  END IF;
573	
574	  -- ── CONFERÊNCIA ──────────────────────────────────────────────────────────────
575	  IF p_etapa = 'conferencia' THEN
576	    IF v_etiqueta.foi_conferida THEN
577	      RETURN jsonb_build_object(
578	        'ok', false,
579	        'erro', format('Etiqueta %s ja esta com status "conferida" — bip duplicado nesta etapa', p_uid),
580	        'etiqueta', to_jsonb(v_etiqueta),
581	        'status_anterior', v_status_anterior, 'status_novo', v_status_anterior
582	      );
583	    END IF;
584	    UPDATE public.etiquetas_qr
585	       SET foi_conferida = TRUE, conferida_at = NOW(), conferida_por = v_user_id,
586	           loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
587	     WHERE uid = p_uid RETURNING * INTO v_etiqueta;
588	    INSERT INTO public.etiquetas_qr_eventos (
589	      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
590	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
591	    ) VALUES (
592	      p_uid, 'bipada_conferencia', 'conferencia', v_status_anterior, v_status_anterior,
593	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
594	      p_contexto - 'payload'
595	    );
596	    RETURN jsonb_build_object(
597	      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
598	      'status_anterior', v_status_anterior, 'status_novo', v_status_anterior,
599	      'alertas', v_alertas, 'backfilled', false
600	    );
601	  END IF;
602	
603	  -- ── EXPOSIÇÃO (container inteiro → vitrine) ──────────────────────────────────
604	  IF p_etapa = 'exposicao' THEN
605	    IF v_etiqueta.status NOT IN ('gerada','recebida','aberta') THEN
606	      RETURN jsonb_build_object(
607	        'ok', false,
608	        -- "ja esta com status" mantém o match de isDuplicateBipError no frontend (re-bip vira âmbar, não erro)
609	        'erro', format('Etiqueta %s ja esta com status "%s" — nao pode ir pra expositora', p_uid, v_status_anterior),
610	        'etiqueta', to_jsonb(v_etiqueta),
611	        'status_anterior', v_status_anterior, 'status_novo', v_status_anterior
612	      );
613	    END IF;
614	
615	    v_loja_eff := COALESCE(v_loja_id, v_etiqueta.loja_atual_id);
616	    IF v_loja_eff IS NULL THEN
617	      RETURN jsonb_build_object('ok', false, 'erro', 'Exposicao exige loja conhecida (contexto ou etiqueta)');
618	    END IF;
619	
620	    v_qtd_expor := COALESCE(v_etiqueta.quantidade_disponivel, v_etiqueta.quantidade_interna, 1);
621	    IF v_qtd_expor <= 0 THEN
622	      RETURN jsonb_build_object('ok', false, 'erro', 'Container vazio — nada a expor',
623	                                'etiqueta', to_jsonb(v_etiqueta));
624	    END IF;
625	
626	    SELECT quantidade_atual INTO v_est_ant
627	      FROM public.estoque
628	     WHERE produto_master_id = v_etiqueta.produto_master_id AND loja_id = v_loja_eff
629	     FOR UPDATE;
630	    v_est_ant := COALESCE(v_est_ant, 0);
631	
632	    -- saída do estoque; trigger credita expositora na mesma transação
633	    INSERT INTO public.movimentacoes (
634	      produto_master_id, tipo_movimentacao, quantidade,
635	      quantidade_anterior, quantidade_nova, motivo, observacoes,
636	      data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
637	    ) VALUES (
638	      v_etiqueta.produto_master_id, 'saida', v_qtd_expor,
639	      v_est_ant, v_est_ant - v_qtd_expor,
640	      'saida_inteira_exposicao',
641	      format('Exposicao na vitrine — UID %s', p_uid),
642	      NOW(), v_loja_eff, v_etiqueta.lote_id, p_uid
643	    );
644	
645	    UPDATE public.etiquetas_qr
646	       SET status = 'consumida', consumida_inteira = TRUE, quantidade_disponivel = 0,
647	           loja_atual_id = v_loja_eff
648	     WHERE uid = p_uid RETURNING * INTO v_etiqueta;
649	
650	    INSERT INTO public.etiquetas_qr_eventos (
651	      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
652	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
653	    ) VALUES (
654	      p_uid, 'bipada_exposicao', 'exposicao', v_status_anterior, 'consumida',
655	      v_loja_eff, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
656	      (p_contexto - 'payload') || jsonb_build_object('quantidade_exposta', v_qtd_expor)
657	    );
658	
659	    RETURN jsonb_build_object(
660	      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
661	      'status_anterior', v_status_anterior, 'status_novo', 'consumida',
662	      'quantidade_exposta', v_qtd_expor,
663	      'alertas', v_alertas, 'backfilled', false
664	    );
665	  END IF;
666	
667	  -- ── TRANSIÇÕES DE STATUS (entrada/saida/consumo/descarte) ───────────────────
668	  v_status_novo := CASE p_etapa
669	    WHEN 'saida' THEN
670	      CASE WHEN v_etiqueta.status IN ('gerada','recebida','aberta','consumida') THEN 'em_transito'
671	           ELSE NULL END
672	    WHEN 'entrada' THEN
673	      CASE WHEN v_etiqueta.status IN ('em_transito','gerada','aberta','consumida') THEN 'recebida'
674	           WHEN v_etiqueta.status = 'recebida'
675	                AND v_loja_id IS DISTINCT FROM v_etiqueta.loja_atual_id THEN 'recebida'
676	           ELSE NULL END
677	    WHEN 'consumo'  THEN 'consumida'
678	    WHEN 'descarte' THEN 'descartada'
679	  END;
680	
681	  IF v_status_novo IS NULL THEN
682	    RETURN jsonb_build_object(
683	      'ok', false,
684	      'erro', format('Etiqueta %s ja esta com status "%s" — bip duplicado nesta etapa', p_uid, v_status_anterior),
685	      'etiqueta', to_jsonb(v_etiqueta)
686	    );
687	  END IF;
688	
689	  UPDATE public.etiquetas_qr
690	     SET status = v_status_novo,
691	         loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
692	   WHERE uid = p_uid RETURNING * INTO v_etiqueta;
693	
694	  INSERT INTO public.etiquetas_qr_eventos (
695	    etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
696	    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
697	  ) VALUES (
698	    p_uid, 'bipada_' || p_etapa, p_etapa, v_status_anterior, v_status_novo,
699	    v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
700	    p_contexto - 'payload'
701	  );
702	
703	  RETURN jsonb_build_object(
704	    'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
705	    'status_anterior', v_status_anterior, 'status_novo', v_status_novo,
706	    'alertas', v_alertas, 'backfilled', false
707	  );
708	END;
709	$function$;
710	
711	-- ─────────────────────────────────────────────────────────────────────────────
712	-- 8) bipar_retirada_avulsa: contexto.destino = 'expositora' → a própria RPC
713	--    registra a movimentação de saída (motivo 'retirada_avulsa_exposicao');
714	--    o trigger credita a expositora. Frontend NÃO insere movimentação nesse caso
715	--    (resposta traz movimentacao_registrada = true).
716	--    Sem destino (default 'saida'): comportamento idêntico ao atual.
717	-- ─────────────────────────────────────────────────────────────────────────────
718	
719	CREATE OR REPLACE FUNCTION public.bipar_retirada_avulsa(p_uid text, p_quantidade numeric, p_contexto jsonb DEFAULT '{}'::jsonb)
720	 RETURNS jsonb
721	 LANGUAGE plpgsql
722	 SECURITY DEFINER
723	 SET search_path TO 'public'
724	AS $function$
725	DECLARE
726	  v_etiqueta            public.etiquetas_qr%ROWTYPE;
727	  v_user_id             uuid := auth.uid();
728	  v_user_nome           text;
729	  v_loja_id             integer;
730	  v_referencia_tipo     text;
731	  v_referencia_id       text;
732	  v_payload             jsonb;
733	  v_disponivel_apos     numeric;
734	  v_status_anterior     text;
735	  v_status_novo         text;
736	  v_pid_text            text;
737	  v_pid_int             integer;
738	  v_lote_uuid           uuid;
739	  v_produto_nome        text;
740	  v_lote_codigo         text;
741	  v_lote_validade       date;
742	  v_qty_interna         numeric;
743	  -- destino expositora
744	  v_destino             text;
745	  v_loja_eff            integer;
746	  v_est_ant             numeric;
747	  v_mov_registrada      boolean := false;
748	BEGIN
749	  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
750	    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade deve ser maior que zero');
751	  END IF;
752	
753	  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
754	  v_referencia_tipo := p_contexto->>'referencia_tipo';
755	  v_referencia_id   := p_contexto->>'referencia_id';
756	  v_payload         := p_contexto->'payload';
757	  v_destino         := COALESCE(NULLIF(p_contexto->>'destino',''), 'saida');
758	
759	  IF v_destino NOT IN ('saida','expositora') THEN
760	    RETURN jsonb_build_object('ok', false, 'erro', 'Destino invalido: ' || v_destino);
761	  END IF;
762	
763	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid FOR UPDATE;
764	
765	  -- ===== BACKFILL legacy: etiqueta sem row mas com payload no QR =====
766	  IF NOT FOUND THEN
767	    IF v_payload IS NULL THEN
768	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao encontrada (sem payload para backfill)');
769	    END IF;
770	    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
771	    IF v_pid_text IS NULL OR v_pid_text = '' THEN
772	      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto');
773	    END IF;
774	    v_pid_int     := v_pid_text::integer;
775	    v_lote_uuid   := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
776	    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);
777	
778	    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
779	    IF v_lote_uuid IS NOT NULL THEN
780	      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade FROM public.lotes WHERE id = v_lote_uuid;
781	    END IF;
782	
783	    INSERT INTO public.etiquetas_qr (
784	      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
785	      quantidade_disponivel, consumida_inteira,
786	      produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
787	      loja_origem_id, loja_atual_id, status, tipo_embalagem,
788	      backfilled, qr_payload
789	    ) VALUES (
790	      p_uid, v_pid_int, v_lote_uuid,
791	      COALESCE(v_payload->>'emb', v_payload->>'n'),
792	      v_qty_interna, v_qty_interna, false,
793	      v_produto_nome, v_lote_codigo, v_lote_validade,
794	      NULL, v_loja_id, 'gerada',
795	      COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'),
796	      true, v_payload
797	    )
798	    RETURNING * INTO v_etiqueta;
799	
800	    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
801	      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
802	      VALUES (p_uid, 'backfilled', 'backfill', NULL, 'gerada',
803	      v_loja_id, v_user_id, COALESCE((SELECT raw_user_meta_data->>'nome' FROM auth.users WHERE id = v_user_id), NULL),
804	      v_referencia_tipo, v_referencia_id,
805	      jsonb_build_object('etapa_origem', 'retirada_avulsa', 'payload', v_payload));
806	  END IF;
807	
808	  IF v_etiqueta.consumida_inteira OR v_etiqueta.status = 'consumida' THEN
809	    RETURN jsonb_build_object('ok', false,
810	      'erro', format('Etiqueta %s ja foi consumida totalmente', p_uid),
811	      'etiqueta', to_jsonb(v_etiqueta));
812	  END IF;
813	  IF v_etiqueta.status = 'descartada' THEN
814	    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada', 'etiqueta', to_jsonb(v_etiqueta));
815	  END IF;
816	
817	  IF p_quantidade > v_etiqueta.quantidade_disponivel THEN
818	    RETURN jsonb_build_object('ok', false,
819	      'erro', format('Container so tem %s disponivel (pediu %s)', v_etiqueta.quantidade_disponivel, p_quantidade),
820	      'etiqueta', to_jsonb(v_etiqueta));
821	  END IF;
822	
823	  -- destino expositora exige loja conhecida — validar ANTES de qualquer escrita
824	  v_loja_eff := COALESCE(v_loja_id, v_etiqueta.loja_atual_id);
825	  IF v_destino = 'expositora' AND v_loja_eff IS NULL THEN
826	    RETURN jsonb_build_object('ok', false, 'erro', 'Destino expositora exige loja conhecida (contexto ou etiqueta)');
827	  END IF;
828	
829	  v_disponivel_apos := v_etiqueta.quantidade_disponivel - p_quantidade;
830	  v_status_anterior := v_etiqueta.status;
831	  v_status_novo := CASE
832	    WHEN v_disponivel_apos = 0 THEN 'consumida'
833	    WHEN v_disponivel_apos < v_etiqueta.quantidade_interna THEN 'aberta'
834	    ELSE v_status_anterior
835	  END;
836	
837	  UPDATE public.etiquetas_qr SET
838	    quantidade_disponivel = v_disponivel_apos,
839	    consumida_inteira     = (v_disponivel_apos = 0),
840	    status                = v_status_novo,
841	    loja_atual_id         = COALESCE(v_loja_id, loja_atual_id)
842	  WHERE uid = p_uid RETURNING * INTO v_etiqueta;
843	
844	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome FROM auth.users WHERE id = v_user_id;
845	
846	  INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
847	    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
848	    VALUES (p_uid,
849	      CASE WHEN v_disponivel_apos = 0 THEN 'consumida_total' ELSE 'retirada_avulsa' END,
850	      'consumo', v_status_anterior, v_status_novo,
851	      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
852	      jsonb_build_object(
853	        'quantidade_retirada', p_quantidade,
854	        'quantidade_disponivel_antes', v_etiqueta.quantidade_interna - v_disponivel_apos + p_quantidade,
855	        'quantidade_disponivel_apos', v_disponivel_apos,
856	        'consumida_inteira', v_etiqueta.consumida_inteira,
857	        'destino', v_destino));
858	
859	  -- destino expositora: movimentação de saída do estoque registrada AQUI
860	  -- (trigger credita a expositora na mesma transação)
861	  IF v_destino = 'expositora' THEN
862	    SELECT quantidade_atual INTO v_est_ant
863	      FROM public.estoque
864	     WHERE produto_master_id = v_etiqueta.produto_master_id AND loja_id = v_loja_eff
865	     FOR UPDATE;
866	    v_est_ant := COALESCE(v_est_ant, 0);
867	
868	    INSERT INTO public.movimentacoes (
869	      produto_master_id, tipo_movimentacao, quantidade,
870	      quantidade_anterior, quantidade_nova, motivo, observacoes,
871	      data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
872	    ) VALUES (
873	      v_etiqueta.produto_master_id, 'saida', p_quantidade,
874	      v_est_ant, v_est_ant - p_quantidade,
875	      'retirada_avulsa_exposicao',
876	      format('Retirada avulsa pra vitrine — UID %s', p_uid),
877	      NOW(), v_loja_eff, v_etiqueta.lote_id, p_uid
878	    );
879	    v_mov_registrada := true;
880	  END IF;
881	
882	  RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta),
883	    'quantidade_retirada', p_quantidade, 'quantidade_disponivel', v_disponivel_apos,
884	    'consumida_inteira', v_etiqueta.consumida_inteira,
885	    'status_anterior', v_status_anterior, 'status_novo', v_status_novo,
886	    'destino', v_destino, 'movimentacao_registrada', v_mov_registrada);
887	END;
888	$function$;
889	
890	-- ─────────────────────────────────────────────────────────────────────────────
891	-- 9) tg_movimentacoes_sync_estoque_lotes: motivos de exposição também
892	--    sincronizam estoque_lotes (o lote físico saiu da câmara). Guard
893	--    app.skip_lote_reconcile preservado — única mudança é a lista de motivos.
894	-- ─────────────────────────────────────────────────────────────────────────────
895	
896	CREATE OR REPLACE FUNCTION public.tg_movimentacoes_sync_estoque_lotes()
897	 RETURNS trigger
898	 LANGUAGE plpgsql
899	 SECURITY DEFINER
900	 SET search_path TO 'public'
901	AS $function$
902	BEGIN
903	  IF COALESCE(NEW.motivo,'') NOT IN (
904	       'scanner_lote', 'contagem_caixa', 'ajuste_lote_manual',
905	       'saida_inteira', 'retirada_avulsa', 'adicao_avulsa',
906	       'saida_inteira_exposicao', 'retirada_avulsa_exposicao'
907	     ) THEN
908	    RETURN NEW;
909	  END IF;
910	
911	  IF NEW.lote_id IS NULL OR NEW.produto_master_id IS NULL THEN
912	    RETURN NEW;
913	  END IF;
914	
915	  -- Sinaliza que a alteracao em estoque_lotes veio de uma movimentacao,
916	  -- pra sync_estoque_from_lotes NAO criar lancamento fantasma.
917	  PERFORM set_config('app.skip_lote_reconcile', '1', true);
918	
919	  IF NEW.tipo_movimentacao = 'entrada' THEN
920	    UPDATE public.estoque_lotes
921	       SET quantidade = GREATEST(0, quantidade + NEW.quantidade)
922	     WHERE lote_id = NEW.lote_id
923	       AND produto_id = NEW.produto_master_id
924	       AND loja_id = NEW.loja_id;
925	
926	  ELSIF NEW.tipo_movimentacao = 'saida' THEN
927	    UPDATE public.estoque_lotes
928	       SET quantidade = GREATEST(0, quantidade - NEW.quantidade)
929	     WHERE lote_id = NEW.lote_id
930	       AND produto_id = NEW.produto_master_id
931	       AND loja_id = NEW.loja_id;
932	  END IF;
933	
934	  -- Sem linha pra esse (lote, produto, loja) e e entrada -> cria com a loja correta.
935	  IF NOT FOUND AND NEW.tipo_movimentacao = 'entrada' THEN
936	    INSERT INTO public.estoque_lotes (lote_id, produto_id, loja_id, quantidade)
937	    VALUES (NEW.lote_id, NEW.produto_master_id, NEW.loja_id, NEW.quantidade);
938	  END IF;
939	
940	  RETURN NEW;
941	END;
942	$function$;
943	
944	-- ─────────────────────────────────────────────────────────────────────────────
945	-- 10) atualizar_estoque_e_alertas: alertas passam a comparar o TOTAL EM LOJA
946	--     (estoque câmara + expositora) — evita alarme falso quando o estoque
947	--     simplesmente subiu pra vitrine. Upsert de estoque inalterado.
948	--     Ramo legacy (produto_id) inalterado.
949	-- ─────────────────────────────────────────────────────────────────────────────
950	
951	CREATE OR REPLACE FUNCTION public.atualizar_estoque_e_alertas()
952	 RETURNS trigger
953	 LANGUAGE plpgsql
954	 SET search_path TO 'public', 'pg_temp'
955	AS $function$
956	DECLARE
957	    estoque_atual DECIMAL(10,3);
958	    estoque_minimo DECIMAL(10,3);
959	    expositora_qtd DECIMAL(10,3);
960	    total_loja DECIMAL(10,3);
961	BEGIN
962	    -- Scenario 1: New System (Master ID)
963	    IF NEW.produto_master_id IS NOT NULL THEN
964	        -- Upsert into estoque using (produto_master_id, loja_id)
965	        -- We assume 'estoque_produto_master_loja_unique' constraint exists on (produto_master_id, loja_id)
966	        INSERT INTO estoque (produto_master_id, quantidade_atual, ultima_movimentacao, ultimo_usuario_id, loja_id)
967	        VALUES (NEW.produto_master_id, NEW.quantidade_nova, NEW.data_movimentacao, NEW.usuario_id, NEW.loja_id)
968	        ON CONFLICT (produto_master_id, loja_id)
969	        DO UPDATE SET
970	            quantidade_atual = EXCLUDED.quantidade_atual,
971	            ultima_movimentacao = EXCLUDED.ultima_movimentacao,
972	            ultimo_usuario_id = EXCLUDED.ultimo_usuario_id,
973	            updated_at = NOW();
974	
975	        -- Check Alerts (sobre o TOTAL em loja: câmara + expositora)
976	        SELECT quantidade_atual, quantidade_minima
977	        INTO estoque_atual, estoque_minimo
978	        FROM estoque
979	        WHERE produto_master_id = NEW.produto_master_id AND loja_id = NEW.loja_id;
980	
981	        SELECT quantidade INTO expositora_qtd
982	        FROM expositora_estoque
983	        WHERE produto_master_id = NEW.produto_master_id AND loja_id = NEW.loja_id;
984	
985	        total_loja := COALESCE(estoque_atual, 0) + COALESCE(expositora_qtd, 0);
986	
987	        IF estoque_atual IS NOT NULL AND estoque_minimo IS NOT NULL THEN
988	            IF total_loja <= 0 THEN
989	                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
990	                VALUES (NEW.produto_master_id, NEW.loja_id, 'sem_estoque', total_loja, estoque_minimo);
991	            ELSIF total_loja <= (estoque_minimo * 0.5) THEN
992	                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
993	                VALUES (NEW.produto_master_id, NEW.loja_id, 'critico', total_loja, estoque_minimo);
994	            ELSIF total_loja <= estoque_minimo THEN
995	                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
996	                VALUES (NEW.produto_master_id, NEW.loja_id, 'baixo', total_loja, estoque_minimo);
997	            END IF;
998	        END IF;
999	
1000	    -- Scenario 2: Legacy System (Product ID)
1001	    ELSIF NEW.produto_id IS NOT NULL THEN
1002	        -- Upsert into estoque using (produto_id, loja_id)
1003	        INSERT INTO estoque (produto_id, quantidade_atual, ultima_movimentacao, ultimo_usuario_id, loja_id)
1004	        VALUES (NEW.produto_id, NEW.quantidade_nova, NEW.data_movimentacao, NEW.usuario_id, NEW.loja_id)
1005	        ON CONFLICT (produto_id, loja_id)
1006	        DO UPDATE SET
1007	            quantidade_atual = EXCLUDED.quantidade_atual,
1008	            ultima_movimentacao = EXCLUDED.ultima_movimentacao,
1009	            ultimo_usuario_id = EXCLUDED.ultimo_usuario_id,
1010	            updated_at = NOW();
1011	
1012	        -- Check Alerts
1013	        SELECT quantidade_atual, quantidade_minima
1014	        INTO estoque_atual, estoque_minimo
1015	        FROM estoque
1016	        WHERE produto_id = NEW.produto_id AND loja_id = NEW.loja_id;
1017	
1018	        IF estoque_atual IS NOT NULL AND estoque_minimo IS NOT NULL THEN
1019	             IF estoque_atual <= 0 THEN
1020	                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
1021	                VALUES (NEW.produto_id, NEW.loja_id, 'sem_estoque', estoque_atual, estoque_minimo);
1022	            ELSIF estoque_atual <= (estoque_minimo * 0.5) THEN
1023	                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
1024	                VALUES (NEW.produto_id, NEW.loja_id, 'critico', estoque_atual, estoque_minimo);
1025	            ELSIF estoque_atual <= estoque_minimo THEN
1026	                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
1027	                VALUES (NEW.produto_id, NEW.loja_id, 'baixo', estoque_atual, estoque_minimo);
1028	            END IF;
1029	        END IF;
1030	
1031	    END IF;
1032	
1033	    RETURN NEW;
1034	END;
1035	$function$;
