-- =============================================================================
-- EXPOSITORA (Pronta Entrega v2) — controle do estoque exposto no salão
--
-- Modelo: estoque (câmara fria/congelado) → EXPOSITORA (vitrines/balcão) → venda.
-- Total em loja = estoque.quantidade_atual + expositora_estoque.quantidade.
--
-- Ponto único de integração: trigger em movimentacoes. Toda saída de estoque
-- com motivo da família "exposição" credita a expositora NA MESMA TRANSAÇÃO:
--   · 'exposicao'                 → movimentação manual (página Pronta Entrega)
--   · 'saida_inteira_exposicao'   → bip de container inteiro (bipar_etiqueta etapa 'exposicao')
--   · 'retirada_avulsa_exposicao' → retirada parcial com destino expositora
--
-- Saldo da expositora PODE ficar negativo por design — mostra o furo de
-- processo (venda/perda sem registro de subida pra vitrine). Fase 2 (Degust)
-- vai lançar tipo='venda' no ledger.
--
-- Nada destrutivo: pronta_entrega_stock/logs permanecem como histórico.
-- =============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- 1) Tabelas: saldo + ledger append-only
-- ─────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.expositora_estoque (
  id                bigserial PRIMARY KEY,
  produto_master_id integer NOT NULL REFERENCES public.produtos_master(id),
  loja_id           integer NOT NULL REFERENCES public.lojas(id),
  quantidade        numeric NOT NULL DEFAULT 0,  -- pode ser negativa (furo de processo visível)
  updated_at        timestamptz NOT NULL DEFAULT now(),
  UNIQUE (produto_master_id, loja_id)
);

CREATE INDEX IF NOT EXISTS idx_expositora_estoque_loja
  ON public.expositora_estoque (loja_id);

CREATE TABLE IF NOT EXISTS public.expositora_movimentacoes (
  id                bigserial PRIMARY KEY,
  produto_master_id integer NOT NULL REFERENCES public.produtos_master(id),
  loja_id           integer NOT NULL REFERENCES public.lojas(id),
  tipo              text    NOT NULL CHECK (tipo IN ('entrada','saida','ajuste','venda')),
  quantidade        numeric NOT NULL,            -- magnitude do movimento (sempre > 0)
  saldo_anterior    numeric NOT NULL,
  saldo_novo        numeric NOT NULL,
  motivo            text    NOT NULL,
  movimentacao_id   integer REFERENCES public.movimentacoes(id) ON DELETE SET NULL,
  etiqueta_qr_uid   text,                        -- trace; sem FK de propósito (etiquetas podem ser limpas)
  usuario_id        uuid,
  usuario_nome      text,
  observacoes       text,
  created_at        timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_expositora_mov_loja_produto_data
  ON public.expositora_movimentacoes (loja_id, produto_master_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_expositora_mov_loja_data
  ON public.expositora_movimentacoes (loja_id, created_at DESC);

-- RLS: leitura pra authenticated; escrita SÓ via funções SECURITY DEFINER
ALTER TABLE public.expositora_estoque        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.expositora_movimentacoes  ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS expositora_estoque_select ON public.expositora_estoque;
CREATE POLICY expositora_estoque_select
  ON public.expositora_estoque FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS expositora_movimentacoes_select ON public.expositora_movimentacoes;
CREATE POLICY expositora_movimentacoes_select
  ON public.expositora_movimentacoes FOR SELECT TO authenticated USING (true);

-- ─────────────────────────────────────────────────────────────────────────────
-- 2) Nova etapa 'exposicao' no CHECK de etiquetas_qr_eventos
-- ─────────────────────────────────────────────────────────────────────────────

ALTER TABLE public.etiquetas_qr_eventos
  DROP CONSTRAINT IF EXISTS etiquetas_qr_eventos_etapa_check;
ALTER TABLE public.etiquetas_qr_eventos
  ADD CONSTRAINT etiquetas_qr_eventos_etapa_check CHECK (etapa = ANY (ARRAY[
    'geracao'::text, 'separacao'::text, 'conferencia'::text, 'entrada'::text,
    'saida'::text, 'consumo'::text, 'descarte'::text, 'reposicao'::text,
    'backfill'::text, 'exposicao'::text
  ]));

-- ─────────────────────────────────────────────────────────────────────────────
-- 3) Helper interno: aplica delta no saldo da expositora + grava ledger
--    (lock por linha; cria a linha zerada se não existir)
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.fn_expositora_aplicar(
  p_produto_master_id integer,
  p_loja_id           integer,
  p_delta             numeric,   -- positivo soma, negativo subtrai
  p_tipo              text,      -- 'entrada' | 'saida' | 'ajuste' | 'venda'
  p_motivo            text,
  p_movimentacao_id   integer DEFAULT NULL,
  p_etiqueta_qr_uid   text    DEFAULT NULL,
  p_usuario_id        uuid    DEFAULT NULL,
  p_usuario_nome      text    DEFAULT NULL,
  p_observacoes       text    DEFAULT NULL
) RETURNS numeric
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_saldo_anterior numeric;
  v_saldo_novo     numeric;
BEGIN
  IF p_delta IS NULL OR p_delta = 0 THEN
    SELECT quantidade INTO v_saldo_anterior
      FROM public.expositora_estoque
     WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;
    RETURN COALESCE(v_saldo_anterior, 0);
  END IF;

  -- garante a linha e trava pra leitura consistente do saldo
  INSERT INTO public.expositora_estoque (produto_master_id, loja_id, quantidade)
  VALUES (p_produto_master_id, p_loja_id, 0)
  ON CONFLICT (produto_master_id, loja_id) DO NOTHING;

  SELECT quantidade INTO v_saldo_anterior
    FROM public.expositora_estoque
   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
   FOR UPDATE;

  v_saldo_novo := v_saldo_anterior + p_delta;

  UPDATE public.expositora_estoque
     SET quantidade = v_saldo_novo, updated_at = now()
   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;

  INSERT INTO public.expositora_movimentacoes (
    produto_master_id, loja_id, tipo, quantidade, saldo_anterior, saldo_novo,
    motivo, movimentacao_id, etiqueta_qr_uid, usuario_id, usuario_nome, observacoes
  ) VALUES (
    p_produto_master_id, p_loja_id, p_tipo, ABS(p_delta), v_saldo_anterior, v_saldo_novo,
    p_motivo, p_movimentacao_id, p_etiqueta_qr_uid, p_usuario_id, p_usuario_nome, p_observacoes
  );

  RETURN v_saldo_novo;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_expositora_aplicar(integer,integer,numeric,text,text,integer,text,uuid,text,text) FROM PUBLIC, anon;

-- ─────────────────────────────────────────────────────────────────────────────
-- 4) Trigger em movimentacoes: saída com motivo de exposição → credita expositora
--    (mesma transação que o débito de estoque feito por atualizar_estoque_e_alertas)
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.tg_movimentacoes_expositora()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id   uuid := auth.uid();
  v_user_nome text;
BEGIN
  IF NEW.tipo_movimentacao <> 'saida'
     OR COALESCE(NEW.motivo,'') NOT IN ('exposicao','saida_inteira_exposicao','retirada_avulsa_exposicao') THEN
    RETURN NEW;
  END IF;
  IF NEW.produto_master_id IS NULL OR NEW.loja_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome
    FROM auth.users WHERE id = v_user_id;

  PERFORM public.fn_expositora_aplicar(
    NEW.produto_master_id, NEW.loja_id, NEW.quantidade,
    'entrada', NEW.motivo, NEW.id, NEW.etiqueta_qr_uid,
    v_user_id, v_user_nome, NEW.observacoes
  );

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_movimentacoes_expositora ON public.movimentacoes;
CREATE TRIGGER trg_movimentacoes_expositora
AFTER INSERT ON public.movimentacoes
FOR EACH ROW EXECUTE FUNCTION public.tg_movimentacoes_expositora();

-- ─────────────────────────────────────────────────────────────────────────────
-- 5) RPC: mover manualmente do estoque pra expositora (página Pronta Entrega)
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.mover_para_expositora(
  p_produto_master_id integer,
  p_loja_id           integer,
  p_quantidade        numeric,
  p_observacoes       text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_estoque_anterior numeric;
  v_estoque_novo     numeric;
  v_expositora       numeric;
  v_alertas          jsonb := '[]'::jsonb;
  v_restante         numeric;
  v_baixa            numeric;
  r                  RECORD;
BEGIN
  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade deve ser maior que zero');
  END IF;
  IF p_loja_id IS NULL OR p_loja_id = 1 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Expositora é por loja — fábrica não tem vitrine');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.produtos_master WHERE id = p_produto_master_id AND ativo = true) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Produto não encontrado ou inativo');
  END IF;

  SELECT quantidade_atual INTO v_estoque_anterior
    FROM public.estoque
   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
   FOR UPDATE;

  v_estoque_anterior := COALESCE(v_estoque_anterior, 0);
  v_estoque_novo     := v_estoque_anterior - p_quantidade;

  IF v_estoque_novo < 0 THEN
    v_alertas := v_alertas || jsonb_build_array(
      format('Estoque da câmara ficou negativo (%s) — confira a contagem', v_estoque_novo));
  END IF;

  -- Baixa FIFO em estoque_lotes (validade mais próxima primeiro) pra manter
  -- lotes ↔ estoque em sincronia. Sem isso, a próxima edição direta de
  -- estoque_lotes dispararia sync_estoque_from_lotes, que REVERTERIA esta
  -- baixa via 'sync_lote_auto' (produto contado em dobro: câmara + vitrine).
  -- Guard transacional impede o reconciliador de reagir a ESTA baixa.
  PERFORM set_config('app.skip_lote_reconcile', '1', true);
  v_restante := p_quantidade;
  FOR r IN
    SELECT el.id, el.quantidade
      FROM public.estoque_lotes el
      LEFT JOIN public.lotes l ON l.id = el.lote_id
     WHERE el.produto_id = p_produto_master_id
       AND el.loja_id = p_loja_id
       AND el.quantidade > 0
     ORDER BY l.data_validade NULLS LAST, el.id
     FOR UPDATE OF el
  LOOP
    EXIT WHEN v_restante <= 0;
    v_baixa := LEAST(r.quantidade, v_restante);
    UPDATE public.estoque_lotes SET quantidade = quantidade - v_baixa WHERE id = r.id;
    v_restante := v_restante - v_baixa;
  END LOOP;

  -- débito do estoque (trigger atualizar_estoque_e_alertas) +
  -- crédito da expositora (trigger tg_movimentacoes_expositora) — atômico
  INSERT INTO public.movimentacoes (
    produto_master_id, tipo_movimentacao, quantidade,
    quantidade_anterior, quantidade_nova, motivo, observacoes,
    data_movimentacao, loja_id
  ) VALUES (
    p_produto_master_id, 'saida', p_quantidade,
    v_estoque_anterior, v_estoque_novo, 'exposicao',
    COALESCE(p_observacoes, 'Movido para expositora'),
    now(), p_loja_id
  );

  SELECT quantidade INTO v_expositora
    FROM public.expositora_estoque
   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;

  RETURN jsonb_build_object(
    'ok', true,
    'estoque_anterior',  v_estoque_anterior,
    'estoque_novo',      v_estoque_novo,
    'expositora_saldo',  COALESCE(v_expositora, 0),
    'alertas',           v_alertas
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.mover_para_expositora(integer,integer,numeric,text) FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.mover_para_expositora(integer,integer,numeric,text) TO authenticated;

-- ─────────────────────────────────────────────────────────────────────────────
-- 6) RPC: ajuste da expositora com motivo (perda, vencido, degustação,
--    consumo interno, recontagem/contagem inicial). NÃO mexe no estoque.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.ajustar_expositora(
  p_produto_master_id integer,
  p_loja_id           integer,
  p_quantidade        numeric,            -- delta (modo 'delta') ou saldo alvo (modo 'absoluto')
  p_modo              text DEFAULT 'delta',
  p_motivo            text DEFAULT 'outro',
  p_observacoes       text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id      uuid := auth.uid();
  v_user_nome    text;
  v_saldo_atual  numeric;
  v_delta        numeric;
  v_saldo_novo   numeric;
BEGIN
  IF p_modo NOT IN ('delta','absoluto') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Modo inválido: ' || COALESCE(p_modo,'<null>'));
  END IF;
  IF p_motivo NOT IN ('perda','vencido','degustacao','consumo_interno','recontagem','contagem_inicial','outro') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Motivo inválido: ' || COALESCE(p_motivo,'<null>'));
  END IF;
  IF p_quantidade IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade obrigatória');
  END IF;
  IF p_loja_id IS NULL OR p_loja_id = 1 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Expositora é por loja — fábrica não tem vitrine');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.produtos_master WHERE id = p_produto_master_id) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Produto não encontrado');
  END IF;

  -- garante linha + trava antes de calcular delta (modo absoluto depende do saldo atual)
  INSERT INTO public.expositora_estoque (produto_master_id, loja_id, quantidade)
  VALUES (p_produto_master_id, p_loja_id, 0)
  ON CONFLICT (produto_master_id, loja_id) DO NOTHING;

  SELECT quantidade INTO v_saldo_atual
    FROM public.expositora_estoque
   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
   FOR UPDATE;

  v_delta := CASE WHEN p_modo = 'absoluto' THEN p_quantidade - v_saldo_atual ELSE p_quantidade END;

  IF v_delta = 0 THEN
    RETURN jsonb_build_object('ok', true, 'saldo', v_saldo_atual, 'delta', 0,
                              'mensagem', 'Saldo já estava no valor informado');
  END IF;

  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome
    FROM auth.users WHERE id = v_user_id;

  v_saldo_novo := public.fn_expositora_aplicar(
    p_produto_master_id, p_loja_id, v_delta,
    'ajuste', p_motivo, NULL, NULL,
    v_user_id, v_user_nome, p_observacoes
  );

  RETURN jsonb_build_object('ok', true, 'saldo_anterior', v_saldo_atual,
                            'saldo', v_saldo_novo, 'delta', v_delta);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.ajustar_expositora(integer,integer,numeric,text,text,text) FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.ajustar_expositora(integer,integer,numeric,text,text,text) TO authenticated;

-- ─────────────────────────────────────────────────────────────────────────────
-- 7) bipar_etiqueta: nova etapa 'exposicao' — container inteiro vai pra vitrine.
--    Etiqueta → 'consumida' (desembalada no salão); movimentação de saída do
--    estoque criada AQUI DENTRO (motivo 'saida_inteira_exposicao') pra garantir
--    atomicidade etiqueta + estoque + lotes + expositora.
--    Resto da função idêntico à versão em produção.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.bipar_etiqueta(p_uid text, p_etapa text, p_contexto jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_etiqueta public.etiquetas_qr%ROWTYPE;
  v_user_id uuid := auth.uid();
  v_user_nome text;
  v_status_anterior text;
  v_status_novo text;
  v_loja_id integer;
  v_alertas jsonb := '[]'::jsonb;
  v_referencia_tipo text;
  v_referencia_id text;
  v_payload jsonb;
  v_pid_text text;
  v_pid_int integer;
  v_lote_uuid uuid;
  v_produto_nome text;
  v_lote_codigo text;
  v_lote_validade date;
  v_qty_interna numeric;
  -- exposição
  v_loja_eff integer;
  v_qtd_expor numeric;
  v_est_ant numeric;
BEGIN
  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte','exposicao') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa invalida: ' || p_etapa);
  END IF;

  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome
    FROM auth.users WHERE id = v_user_id;

  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
  v_referencia_tipo := p_contexto->>'referencia_tipo';
  v_referencia_id   := p_contexto->>'referencia_id';
  v_payload         := p_contexto->'payload';

  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;

  -- ── BACKFILL: etiqueta nova (nunca registrada) ──────────────────────────────
  IF NOT FOUND THEN
    IF v_payload IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e sem payload para backfill');
    END IF;

    -- exposição exige loja conhecida (não há etiqueta pra herdar loja_atual_id)
    IF p_etapa = 'exposicao' AND v_loja_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Exposicao exige loja_id no contexto');
    END IF;

    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
    IF v_pid_text IS NULL OR v_pid_text = '' THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto');
    END IF;
    v_pid_int     := v_pid_text::integer;
    v_lote_uuid   := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);

    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;

    -- Resolve lote_id de forma segura: se UUID do payload nao existe, cria/encontra
    -- por codigo+validade ou usa NULL. Nunca insere UUID morto (causa FK error).
    IF v_lote_uuid IS NOT NULL THEN
      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade
        FROM public.lotes WHERE id = v_lote_uuid;
      IF NOT FOUND THEN
        -- UUID morto: tenta resolver por snapshot no payload
        v_lote_codigo  := NULLIF(COALESCE(v_payload->>'lote', v_payload->>'lc'), '');
        v_lote_validade := NULLIF(COALESCE(v_payload->>'val',  v_payload->>'v'),  '')::date;
        IF v_lote_codigo IS NOT NULL AND v_lote_validade IS NOT NULL THEN
          v_lote_uuid := public.find_or_create_lote(
            v_pid_int, v_lote_codigo, v_lote_validade, NULL, NULL
          );
        ELSE
          v_lote_uuid := NULL;  -- sem como resolver; grava sem lote (FK permite NULL)
        END IF;
      END IF;
    END IF;

    INSERT INTO public.etiquetas_qr (
      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
      quantidade_disponivel, consumida_inteira,
      produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
      loja_origem_id, loja_atual_id, status, tipo_embalagem,
      foi_separada, separada_at, separada_por,
      foi_conferida, conferida_at, conferida_por,
      backfilled, qr_payload
    ) VALUES (
      p_uid, v_pid_int, v_lote_uuid,
      COALESCE(v_payload->>'emb', v_payload->>'n'),
      v_qty_interna,
      CASE WHEN p_etapa = 'exposicao' THEN 0 ELSE v_qty_interna END,
      (p_etapa = 'exposicao'),
      v_produto_nome, v_lote_codigo, v_lote_validade,
      NULL, v_loja_id,
      CASE p_etapa
        WHEN 'separacao'  THEN 'gerada'
        WHEN 'conferencia' THEN 'gerada'
        WHEN 'entrada'    THEN 'recebida'
        WHEN 'saida'      THEN 'em_transito'
        WHEN 'consumo'    THEN 'consumida'
        WHEN 'descarte'   THEN 'descartada'
        WHEN 'exposicao'  THEN 'consumida'
      END,
      COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'),
      (p_etapa = 'separacao'),
      CASE WHEN p_etapa = 'separacao' THEN NOW() ELSE NULL END,
      CASE WHEN p_etapa = 'separacao' THEN v_user_id ELSE NULL END,
      (p_etapa = 'conferencia'),
      CASE WHEN p_etapa = 'conferencia' THEN NOW() ELSE NULL END,
      CASE WHEN p_etapa = 'conferencia' THEN v_user_id ELSE NULL END,
      true, v_payload
    ) RETURNING * INTO v_etiqueta;

    -- exposição em backfill: registra a saída do estoque (crédito da expositora
    -- acontece via trigger tg_movimentacoes_expositora)
    IF p_etapa = 'exposicao' THEN
      SELECT quantidade_atual INTO v_est_ant
        FROM public.estoque
       WHERE produto_master_id = v_pid_int AND loja_id = v_loja_id
       FOR UPDATE;
      v_est_ant := COALESCE(v_est_ant, 0);

      INSERT INTO public.movimentacoes (
        produto_master_id, tipo_movimentacao, quantidade,
        quantidade_anterior, quantidade_nova, motivo, observacoes,
        data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
      ) VALUES (
        v_pid_int, 'saida', v_qty_interna,
        v_est_ant, v_est_ant - v_qty_interna,
        'saida_inteira_exposicao',
        format('Exposicao na vitrine (backfill) — UID %s', p_uid),
        NOW(), v_loja_id, v_lote_uuid, p_uid
      );
    END IF;

    v_alertas := v_alertas || jsonb_build_array('Etiqueta antiga registrada retroativamente (backfill)');
    INSERT INTO public.etiquetas_qr_eventos (
      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
    ) VALUES (
      p_uid, 'backfilled', 'backfill', NULL, v_etiqueta.status,
      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
      jsonb_build_object('etapa_origem', p_etapa, 'payload', v_payload)
    );

    RETURN jsonb_build_object(
      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
      'status_anterior', NULL, 'status_novo', v_etiqueta.status,
      'alertas', v_alertas, 'backfilled', true,
      'quantidade_exposta', CASE WHEN p_etapa = 'exposicao' THEN v_qty_interna ELSE NULL END
    );
  END IF;
  -- ── FIM BACKFILL ─────────────────────────────────────────────────────────────

  v_status_anterior := v_etiqueta.status;

  IF v_etiqueta.status = 'descartada' THEN
    RETURN jsonb_build_object(
      'ok', false, 'erro', 'Etiqueta descartada'
        || CASE WHEN v_etiqueta.replaced_by_uid IS NOT NULL
                THEN ' (substituida por ' || v_etiqueta.replaced_by_uid || ')'
                ELSE '' END,
      'etiqueta', to_jsonb(v_etiqueta)
    );
  END IF;

  IF v_etiqueta.lote_validade_snapshot IS NOT NULL
     AND v_etiqueta.lote_validade_snapshot < CURRENT_DATE THEN
    v_alertas := v_alertas || jsonb_build_array(
      format('LOTE VENCIDO em %s', to_char(v_etiqueta.lote_validade_snapshot,'DD/MM/YYYY'))
    );
  END IF;

  -- ── SEPARAÇÃO ────────────────────────────────────────────────────────────────
  IF p_etapa = 'separacao' THEN
    IF v_etiqueta.foi_separada THEN
      RETURN jsonb_build_object(
        'ok', false,
        'erro', format('Etiqueta %s ja esta com status "separada" — bip duplicado nesta etapa', p_uid),
        'etiqueta', to_jsonb(v_etiqueta),
        'status_anterior', v_status_anterior, 'status_novo', v_status_anterior
      );
    END IF;
    UPDATE public.etiquetas_qr
       SET foi_separada = TRUE, separada_at = NOW(), separada_por = v_user_id,
           loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
     WHERE uid = p_uid RETURNING * INTO v_etiqueta;
    INSERT INTO public.etiquetas_qr_eventos (
      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
    ) VALUES (
      p_uid, 'bipada_separacao', 'separacao', v_status_anterior, v_status_anterior,
      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
      p_contexto - 'payload'
    );
    RETURN jsonb_build_object(
      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
      'status_anterior', v_status_anterior, 'status_novo', v_status_anterior,
      'alertas', v_alertas, 'backfilled', false
    );
  END IF;

  -- ── CONFERÊNCIA ──────────────────────────────────────────────────────────────
  IF p_etapa = 'conferencia' THEN
    IF v_etiqueta.foi_conferida THEN
      RETURN jsonb_build_object(
        'ok', false,
        'erro', format('Etiqueta %s ja esta com status "conferida" — bip duplicado nesta etapa', p_uid),
        'etiqueta', to_jsonb(v_etiqueta),
        'status_anterior', v_status_anterior, 'status_novo', v_status_anterior
      );
    END IF;
    UPDATE public.etiquetas_qr
       SET foi_conferida = TRUE, conferida_at = NOW(), conferida_por = v_user_id,
           loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
     WHERE uid = p_uid RETURNING * INTO v_etiqueta;
    INSERT INTO public.etiquetas_qr_eventos (
      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
    ) VALUES (
      p_uid, 'bipada_conferencia', 'conferencia', v_status_anterior, v_status_anterior,
      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
      p_contexto - 'payload'
    );
    RETURN jsonb_build_object(
      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
      'status_anterior', v_status_anterior, 'status_novo', v_status_anterior,
      'alertas', v_alertas, 'backfilled', false
    );
  END IF;

  -- ── EXPOSIÇÃO (container inteiro → vitrine) ──────────────────────────────────
  IF p_etapa = 'exposicao' THEN
    IF v_etiqueta.status NOT IN ('gerada','recebida','aberta') THEN
      RETURN jsonb_build_object(
        'ok', false,
        -- "ja esta com status" mantém o match de isDuplicateBipError no frontend (re-bip vira âmbar, não erro)
        'erro', format('Etiqueta %s ja esta com status "%s" — nao pode ir pra expositora', p_uid, v_status_anterior),
        'etiqueta', to_jsonb(v_etiqueta),
        'status_anterior', v_status_anterior, 'status_novo', v_status_anterior
      );
    END IF;

    v_loja_eff := COALESCE(v_loja_id, v_etiqueta.loja_atual_id);
    IF v_loja_eff IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Exposicao exige loja conhecida (contexto ou etiqueta)');
    END IF;

    v_qtd_expor := COALESCE(v_etiqueta.quantidade_disponivel, v_etiqueta.quantidade_interna, 1);
    IF v_qtd_expor <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Container vazio — nada a expor',
                                'etiqueta', to_jsonb(v_etiqueta));
    END IF;

    SELECT quantidade_atual INTO v_est_ant
      FROM public.estoque
     WHERE produto_master_id = v_etiqueta.produto_master_id AND loja_id = v_loja_eff
     FOR UPDATE;
    v_est_ant := COALESCE(v_est_ant, 0);

    -- saída do estoque; trigger credita expositora na mesma transação
    INSERT INTO public.movimentacoes (
      produto_master_id, tipo_movimentacao, quantidade,
      quantidade_anterior, quantidade_nova, motivo, observacoes,
      data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
    ) VALUES (
      v_etiqueta.produto_master_id, 'saida', v_qtd_expor,
      v_est_ant, v_est_ant - v_qtd_expor,
      'saida_inteira_exposicao',
      format('Exposicao na vitrine — UID %s', p_uid),
      NOW(), v_loja_eff, v_etiqueta.lote_id, p_uid
    );

    UPDATE public.etiquetas_qr
       SET status = 'consumida', consumida_inteira = TRUE, quantidade_disponivel = 0,
           loja_atual_id = v_loja_eff
     WHERE uid = p_uid RETURNING * INTO v_etiqueta;

    INSERT INTO public.etiquetas_qr_eventos (
      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
    ) VALUES (
      p_uid, 'bipada_exposicao', 'exposicao', v_status_anterior, 'consumida',
      v_loja_eff, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
      (p_contexto - 'payload') || jsonb_build_object('quantidade_exposta', v_qtd_expor)
    );

    RETURN jsonb_build_object(
      'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
      'status_anterior', v_status_anterior, 'status_novo', 'consumida',
      'quantidade_exposta', v_qtd_expor,
      'alertas', v_alertas, 'backfilled', false
    );
  END IF;

  -- ── TRANSIÇÕES DE STATUS (entrada/saida/consumo/descarte) ───────────────────
  v_status_novo := CASE p_etapa
    WHEN 'saida' THEN
      CASE WHEN v_etiqueta.status IN ('gerada','recebida','aberta','consumida') THEN 'em_transito'
           ELSE NULL END
    WHEN 'entrada' THEN
      CASE WHEN v_etiqueta.status IN ('em_transito','gerada','aberta','consumida') THEN 'recebida'
           WHEN v_etiqueta.status = 'recebida'
                AND v_loja_id IS DISTINCT FROM v_etiqueta.loja_atual_id THEN 'recebida'
           ELSE NULL END
    WHEN 'consumo'  THEN 'consumida'
    WHEN 'descarte' THEN 'descartada'
  END;

  IF v_status_novo IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'erro', format('Etiqueta %s ja esta com status "%s" — bip duplicado nesta etapa', p_uid, v_status_anterior),
      'etiqueta', to_jsonb(v_etiqueta)
    );
  END IF;

  UPDATE public.etiquetas_qr
     SET status = v_status_novo,
         loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
   WHERE uid = p_uid RETURNING * INTO v_etiqueta;

  INSERT INTO public.etiquetas_qr_eventos (
    etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
  ) VALUES (
    p_uid, 'bipada_' || p_etapa, p_etapa, v_status_anterior, v_status_novo,
    v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
    p_contexto - 'payload'
  );

  RETURN jsonb_build_object(
    'ok', true, 'etiqueta', to_jsonb(v_etiqueta),
    'status_anterior', v_status_anterior, 'status_novo', v_status_novo,
    'alertas', v_alertas, 'backfilled', false
  );
END;
$function$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 8) bipar_retirada_avulsa: contexto.destino = 'expositora' → a própria RPC
--    registra a movimentação de saída (motivo 'retirada_avulsa_exposicao');
--    o trigger credita a expositora. Frontend NÃO insere movimentação nesse caso
--    (resposta traz movimentacao_registrada = true).
--    Sem destino (default 'saida'): comportamento idêntico ao atual.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.bipar_retirada_avulsa(p_uid text, p_quantidade numeric, p_contexto jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_etiqueta            public.etiquetas_qr%ROWTYPE;
  v_user_id             uuid := auth.uid();
  v_user_nome           text;
  v_loja_id             integer;
  v_referencia_tipo     text;
  v_referencia_id       text;
  v_payload             jsonb;
  v_disponivel_apos     numeric;
  v_status_anterior     text;
  v_status_novo         text;
  v_pid_text            text;
  v_pid_int             integer;
  v_lote_uuid           uuid;
  v_produto_nome        text;
  v_lote_codigo         text;
  v_lote_validade       date;
  v_qty_interna         numeric;
  -- destino expositora
  v_destino             text;
  v_loja_eff            integer;
  v_est_ant             numeric;
  v_mov_registrada      boolean := false;
BEGIN
  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade deve ser maior que zero');
  END IF;

  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
  v_referencia_tipo := p_contexto->>'referencia_tipo';
  v_referencia_id   := p_contexto->>'referencia_id';
  v_payload         := p_contexto->'payload';
  v_destino         := COALESCE(NULLIF(p_contexto->>'destino',''), 'saida');

  IF v_destino NOT IN ('saida','expositora') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Destino invalido: ' || v_destino);
  END IF;

  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid FOR UPDATE;

  -- ===== BACKFILL legacy: etiqueta sem row mas com payload no QR =====
  IF NOT FOUND THEN
    IF v_payload IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao encontrada (sem payload para backfill)');
    END IF;
    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
    IF v_pid_text IS NULL OR v_pid_text = '' THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao cadastrada e payload sem produto');
    END IF;
    v_pid_int     := v_pid_text::integer;
    v_lote_uuid   := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;
    v_qty_interna := COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1);

    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
    IF v_lote_uuid IS NOT NULL THEN
      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade FROM public.lotes WHERE id = v_lote_uuid;
    END IF;

    INSERT INTO public.etiquetas_qr (
      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
      quantidade_disponivel, consumida_inteira,
      produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
      loja_origem_id, loja_atual_id, status, tipo_embalagem,
      backfilled, qr_payload
    ) VALUES (
      p_uid, v_pid_int, v_lote_uuid,
      COALESCE(v_payload->>'emb', v_payload->>'n'),
      v_qty_interna, v_qty_interna, false,
      v_produto_nome, v_lote_codigo, v_lote_validade,
      NULL, v_loja_id, 'gerada',
      COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'),
      true, v_payload
    )
    RETURNING * INTO v_etiqueta;

    INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
      VALUES (p_uid, 'backfilled', 'backfill', NULL, 'gerada',
      v_loja_id, v_user_id, COALESCE((SELECT raw_user_meta_data->>'nome' FROM auth.users WHERE id = v_user_id), NULL),
      v_referencia_tipo, v_referencia_id,
      jsonb_build_object('etapa_origem', 'retirada_avulsa', 'payload', v_payload));
  END IF;

  IF v_etiqueta.consumida_inteira OR v_etiqueta.status = 'consumida' THEN
    RETURN jsonb_build_object('ok', false,
      'erro', format('Etiqueta %s ja foi consumida totalmente', p_uid),
      'etiqueta', to_jsonb(v_etiqueta));
  END IF;
  IF v_etiqueta.status = 'descartada' THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada', 'etiqueta', to_jsonb(v_etiqueta));
  END IF;

  IF p_quantidade > v_etiqueta.quantidade_disponivel THEN
    RETURN jsonb_build_object('ok', false,
      'erro', format('Container so tem %s disponivel (pediu %s)', v_etiqueta.quantidade_disponivel, p_quantidade),
      'etiqueta', to_jsonb(v_etiqueta));
  END IF;

  -- destino expositora exige loja conhecida — validar ANTES de qualquer escrita
  v_loja_eff := COALESCE(v_loja_id, v_etiqueta.loja_atual_id);
  IF v_destino = 'expositora' AND v_loja_eff IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Destino expositora exige loja conhecida (contexto ou etiqueta)');
  END IF;

  v_disponivel_apos := v_etiqueta.quantidade_disponivel - p_quantidade;
  v_status_anterior := v_etiqueta.status;
  v_status_novo := CASE
    WHEN v_disponivel_apos = 0 THEN 'consumida'
    WHEN v_disponivel_apos < v_etiqueta.quantidade_interna THEN 'aberta'
    ELSE v_status_anterior
  END;

  UPDATE public.etiquetas_qr SET
    quantidade_disponivel = v_disponivel_apos,
    consumida_inteira     = (v_disponivel_apos = 0),
    status                = v_status_novo,
    loja_atual_id         = COALESCE(v_loja_id, loja_atual_id)
  WHERE uid = p_uid RETURNING * INTO v_etiqueta;

  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome FROM auth.users WHERE id = v_user_id;

  INSERT INTO public.etiquetas_qr_eventos (etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata)
    VALUES (p_uid,
      CASE WHEN v_disponivel_apos = 0 THEN 'consumida_total' ELSE 'retirada_avulsa' END,
      'consumo', v_status_anterior, v_status_novo,
      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
      jsonb_build_object(
        'quantidade_retirada', p_quantidade,
        'quantidade_disponivel_antes', v_etiqueta.quantidade_interna - v_disponivel_apos + p_quantidade,
        'quantidade_disponivel_apos', v_disponivel_apos,
        'consumida_inteira', v_etiqueta.consumida_inteira,
        'destino', v_destino));

  -- destino expositora: movimentação de saída do estoque registrada AQUI
  -- (trigger credita a expositora na mesma transação)
  IF v_destino = 'expositora' THEN
    SELECT quantidade_atual INTO v_est_ant
      FROM public.estoque
     WHERE produto_master_id = v_etiqueta.produto_master_id AND loja_id = v_loja_eff
     FOR UPDATE;
    v_est_ant := COALESCE(v_est_ant, 0);

    INSERT INTO public.movimentacoes (
      produto_master_id, tipo_movimentacao, quantidade,
      quantidade_anterior, quantidade_nova, motivo, observacoes,
      data_movimentacao, loja_id, lote_id, etiqueta_qr_uid
    ) VALUES (
      v_etiqueta.produto_master_id, 'saida', p_quantidade,
      v_est_ant, v_est_ant - p_quantidade,
      'retirada_avulsa_exposicao',
      format('Retirada avulsa pra vitrine — UID %s', p_uid),
      NOW(), v_loja_eff, v_etiqueta.lote_id, p_uid
    );
    v_mov_registrada := true;
  END IF;

  RETURN jsonb_build_object('ok', true, 'etiqueta', to_jsonb(v_etiqueta),
    'quantidade_retirada', p_quantidade, 'quantidade_disponivel', v_disponivel_apos,
    'consumida_inteira', v_etiqueta.consumida_inteira,
    'status_anterior', v_status_anterior, 'status_novo', v_status_novo,
    'destino', v_destino, 'movimentacao_registrada', v_mov_registrada);
END;
$function$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 9) tg_movimentacoes_sync_estoque_lotes: motivos de exposição também
--    sincronizam estoque_lotes (o lote físico saiu da câmara). Guard
--    app.skip_lote_reconcile preservado — única mudança é a lista de motivos.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.tg_movimentacoes_sync_estoque_lotes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(NEW.motivo,'') NOT IN (
       'scanner_lote', 'contagem_caixa', 'ajuste_lote_manual',
       'saida_inteira', 'retirada_avulsa', 'adicao_avulsa',
       'saida_inteira_exposicao', 'retirada_avulsa_exposicao'
     ) THEN
    RETURN NEW;
  END IF;

  IF NEW.lote_id IS NULL OR NEW.produto_master_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Sinaliza que a alteracao em estoque_lotes veio de uma movimentacao,
  -- pra sync_estoque_from_lotes NAO criar lancamento fantasma.
  PERFORM set_config('app.skip_lote_reconcile', '1', true);

  IF NEW.tipo_movimentacao = 'entrada' THEN
    UPDATE public.estoque_lotes
       SET quantidade = GREATEST(0, quantidade + NEW.quantidade)
     WHERE lote_id = NEW.lote_id
       AND produto_id = NEW.produto_master_id
       AND loja_id = NEW.loja_id;

  ELSIF NEW.tipo_movimentacao = 'saida' THEN
    UPDATE public.estoque_lotes
       SET quantidade = GREATEST(0, quantidade - NEW.quantidade)
     WHERE lote_id = NEW.lote_id
       AND produto_id = NEW.produto_master_id
       AND loja_id = NEW.loja_id;
  END IF;

  -- Sem linha pra esse (lote, produto, loja) e e entrada -> cria com a loja correta.
  IF NOT FOUND AND NEW.tipo_movimentacao = 'entrada' THEN
    INSERT INTO public.estoque_lotes (lote_id, produto_id, loja_id, quantidade)
    VALUES (NEW.lote_id, NEW.produto_master_id, NEW.loja_id, NEW.quantidade);
  END IF;

  RETURN NEW;
END;
$function$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 10) atualizar_estoque_e_alertas: alertas passam a comparar o TOTAL EM LOJA
--     (estoque câmara + expositora) — evita alarme falso quando o estoque
--     simplesmente subiu pra vitrine. Upsert de estoque inalterado.
--     Ramo legacy (produto_id) inalterado.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.atualizar_estoque_e_alertas()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    estoque_atual DECIMAL(10,3);
    estoque_minimo DECIMAL(10,3);
    expositora_qtd DECIMAL(10,3);
    total_loja DECIMAL(10,3);
BEGIN
    -- Scenario 1: New System (Master ID)
    IF NEW.produto_master_id IS NOT NULL THEN
        -- Upsert into estoque using (produto_master_id, loja_id)
        -- We assume 'estoque_produto_master_loja_unique' constraint exists on (produto_master_id, loja_id)
        INSERT INTO estoque (produto_master_id, quantidade_atual, ultima_movimentacao, ultimo_usuario_id, loja_id)
        VALUES (NEW.produto_master_id, NEW.quantidade_nova, NEW.data_movimentacao, NEW.usuario_id, NEW.loja_id)
        ON CONFLICT (produto_master_id, loja_id)
        DO UPDATE SET
            quantidade_atual = EXCLUDED.quantidade_atual,
            ultima_movimentacao = EXCLUDED.ultima_movimentacao,
            ultimo_usuario_id = EXCLUDED.ultimo_usuario_id,
            updated_at = NOW();

        -- Check Alerts (sobre o TOTAL em loja: câmara + expositora)
        SELECT quantidade_atual, quantidade_minima
        INTO estoque_atual, estoque_minimo
        FROM estoque
        WHERE produto_master_id = NEW.produto_master_id AND loja_id = NEW.loja_id;

        SELECT quantidade INTO expositora_qtd
        FROM expositora_estoque
        WHERE produto_master_id = NEW.produto_master_id AND loja_id = NEW.loja_id;

        total_loja := COALESCE(estoque_atual, 0) + COALESCE(expositora_qtd, 0);

        IF estoque_atual IS NOT NULL AND estoque_minimo IS NOT NULL THEN
            IF total_loja <= 0 THEN
                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_master_id, NEW.loja_id, 'sem_estoque', total_loja, estoque_minimo);
            ELSIF total_loja <= (estoque_minimo * 0.5) THEN
                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_master_id, NEW.loja_id, 'critico', total_loja, estoque_minimo);
            ELSIF total_loja <= estoque_minimo THEN
                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_master_id, NEW.loja_id, 'baixo', total_loja, estoque_minimo);
            END IF;
        END IF;

    -- Scenario 2: Legacy System (Product ID)
    ELSIF NEW.produto_id IS NOT NULL THEN
        -- Upsert into estoque using (produto_id, loja_id)
        INSERT INTO estoque (produto_id, quantidade_atual, ultima_movimentacao, ultimo_usuario_id, loja_id)
        VALUES (NEW.produto_id, NEW.quantidade_nova, NEW.data_movimentacao, NEW.usuario_id, NEW.loja_id)
        ON CONFLICT (produto_id, loja_id)
        DO UPDATE SET
            quantidade_atual = EXCLUDED.quantidade_atual,
            ultima_movimentacao = EXCLUDED.ultima_movimentacao,
            ultimo_usuario_id = EXCLUDED.ultimo_usuario_id,
            updated_at = NOW();

        -- Check Alerts
        SELECT quantidade_atual, quantidade_minima
        INTO estoque_atual, estoque_minimo
        FROM estoque
        WHERE produto_id = NEW.produto_id AND loja_id = NEW.loja_id;

        IF estoque_atual IS NOT NULL AND estoque_minimo IS NOT NULL THEN
             IF estoque_atual <= 0 THEN
                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_id, NEW.loja_id, 'sem_estoque', estoque_atual, estoque_minimo);
            ELSIF estoque_atual <= (estoque_minimo * 0.5) THEN
                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_id, NEW.loja_id, 'critico', estoque_atual, estoque_minimo);
            ELSIF estoque_atual <= estoque_minimo THEN
                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_id, NEW.loja_id, 'baixo', estoque_atual, estoque_minimo);
            END IF;
        END IF;

    END IF;

    RETURN NEW;
END;
$function$;

